window.DERECH_ARTICLE_SEARCH = [{"title":"מה זה בעצם טיפול רגשי בעזרת כלבים?","url":"https://derech-hakelev.com/pages/articles/emotional-therapy-with-dogs/","entries":[{"id":"article-title-e703fd7ce50f","heading":"תחילת המאמר","text":"מה זה בעצם טיפול רגשי בעזרת כלבים?"},{"id":"article-paragraph-c669cc8a6071","heading":"פתיחת המאמר","text":"כשאנשים שומעים על טיפול רגשי בעזרת כלבים, הם לפעמים מדמיינים מפגש שבו משחקים עם כלב, מלטפים אותו, מלמדים אותו פקודות ובעיקר נהנים. כל אלה בהחלט יכולים להיות חלק מהמפגש, אבל מאחוריהם יש הרבה יותר."},{"id":"article-paragraph-b7b16339197d","heading":"פתיחת המאמר","text":"בטיפול רגשי בעזרת כלבים, הכלב משתלב בתהליך הטיפולי ועוזר לנו לעבוד על קשיים רגשיים, התנהגותיים וחברתיים. לפעמים דרך משחק, לפעמים דרך אילוף ולפעמים פשוט דרך הקשר שנוצר איתו."},{"id":"article-paragraph-23967fa7c81a","heading":"פתיחת המאמר","text":"אז מה בעצם הכלב מוסיף לטיפול?"},{"id":"article-heading-0443a7279fc3","heading":"לפעמים קל יותר להיפתח כשיש כלב בחדר","text":"לפעמים קל יותר להיפתח כשיש כלב בחדר"},{"id":"article-paragraph-1b7e9844d205","heading":"לפעמים קל יותר להיפתח כשיש כלב בחדר","text":"אחד הדברים החשובים ביותר בכל טיפול הוא הקשר בין המטפל למטופל. לפני שאפשר לדבר על קשיים, פחדים או חוויות אישיות, צריך קודם כול להרגיש מספיק בטוחים."},{"id":"article-paragraph-3da2489a8463","heading":"לפעמים קל יותר להיפתח כשיש כלב בחדר","text":"אבל לא כולם מגיעים לטיפול עם רצון לדבר. יש ילדים שמתקשים להיפתח מול מבוגר זר, מתבגרים שמגיעים כי ההורים ביקשו, וגם מבוגרים שלא תמיד מרגישים בנוח לשתף אדם שהם רק הכירו."},{"id":"article-paragraph-e3d46f94b1fc","heading":"לפעמים קל יותר להיפתח כשיש כלב בחדר","text":"כאן הכלב יכול לעשות הבדל משמעותי."},{"id":"article-paragraph-f3705f17f6ec","heading":"לפעמים קל יותר להיפתח כשיש כלב בחדר","text":"במקום להתחיל בשאלות, אפשר להתחיל במשחק, בליטוף או בפעילות משותפת. תשומת הלב כבר לא מופנית רק למטופל, והמפגש הופך לפחות רשמי ומאיים."},{"id":"article-paragraph-b56259869b0e","heading":"לפעמים קל יותר להיפתח כשיש כלב בחדר","text":"מהניסיון שלי, הנוכחות של הכלב יכולה לעזור להוריד מגננות, להפחית התנגדויות וליצור קשר ראשוני בצורה טבעית ולעיתים גם מהירה יותר."},{"id":"article-heading-5a01ba7fbdaa","heading":"לא תמיד צריך לדבר על הקושי כדי לעבוד עליו","text":"לא תמיד צריך לדבר על הקושי כדי לעבוד עליו"},{"id":"article-paragraph-b538c3eb5ef7","heading":"לא תמיד צריך לדבר על הקושי כדי לעבוד עליו","text":"אחד היתרונות הגדולים של טיפול בעזרת כלבים הוא האפשרות לעבוד על דברים תוך כדי התנסות, ולא רק באמצעות שיחה."},{"id":"article-paragraph-371ab2a4b4e5","heading":"לא תמיד צריך לדבר על הקושי כדי לעבוד עליו","text":"למשל, ילד שמתקשה להתמודד עם תסכול יכול לקבל משימה ללמד את הכלב פעולה חדשה. בהתחלה הכול הולך מצוין, אבל פתאום הכלב לא משתף פעולה. הילד מנסה שוב, מתעצבן, אולי אפילו רוצה לוותר."},{"id":"article-paragraph-ddd976c89f79","heading":"לא תמיד צריך לדבר על הקושי כדי לעבוד עליו","text":"זה בדיוק הרגע שבו מתחילה העבודה הטיפולית."},{"id":"article-paragraph-57bf804686aa","heading":"לא תמיד צריך לדבר על הקושי כדי לעבוד עליו","text":"אפשר לעצור, להבין מה קרה, לזהות את הרגשות שעלו ולחשוב יחד מה אפשר לעשות אחרת. בהמשך אפשר גם לנסות שוב ולחוות הצלחה."},{"id":"article-paragraph-bc817a9ce3ab","heading":"לא תמיד צריך לדבר על הקושי כדי לעבוד עליו","text":"כך אפשר לעבוד על ויסות רגשי, דחיית סיפוקים, התמדה, ביטחון עצמי, הצבת גבולות, תקשורת ועוד."},{"id":"article-paragraph-9480d5faea85","heading":"לא תמיד צריך לדבר על הקושי כדי לעבוד עליו","text":"במקום רק לדבר על סבלנות, אנחנו מתרגלים אותה. במקום להסביר איך להתמודד עם כישלון, אנחנו פוגשים אותו בסביבה בטוחה ולומדים להתמודד איתו."},{"id":"article-heading-ac1fd8b7a9fa","heading":"לפעמים קל יותר לדבר על הכלב מאשר על עצמנו","text":"לפעמים קל יותר לדבר על הכלב מאשר על עצמנו"},{"id":"article-paragraph-6e7bedc2af61","heading":"לפעמים קל יותר לדבר על הכלב מאשר על עצמנו","text":"דרך נוספת שבה אני נעזר בכלבים בטיפול היא עבודה השלכתית."},{"id":"article-paragraph-d18237396463","heading":"לפעמים קל יותר לדבר על הכלב מאשר על עצמנו","text":"הרבה פעמים קל יותר לדבר על רגשות, מחשבות או קשיים של מישהו אחר מאשר על שלנו."},{"id":"article-paragraph-abf7ee2390e0","heading":"לפעמים קל יותר לדבר על הכלב מאשר על עצמנו","text":"למשל, אפשר לשאול ילד מה לדעתו הכלב מרגיש כשהוא מגיע למקום חדש, מה עוזר לו להרגיש בטוח או איך הוא מגיב כשלא מבינים אותו."},{"id":"article-paragraph-794586095262","heading":"לפעמים קל יותר לדבר על הכלב מאשר על עצמנו","text":"דרך השיחה על הכלב יכולים לעלות נושאים כמו פחד, בדידות, שייכות, צורך בביטחון או קושי לבקש עזרה."},{"id":"article-paragraph-ad3098c6de1f","heading":"לפעמים קל יותר לדבר על הכלב מאשר על עצמנו","text":"לפעמים השיחה נשארת על הכלב, ולפעמים היא מתפתחת באופן טבעי לשיחה על החיים של המטופל."},{"id":"article-paragraph-4c581e52574f","heading":"לפעמים קל יותר לדבר על הכלב מאשר על עצמנו","text":"היתרון הוא שלא חייבים לשאול שאלות ישירות או ללחוץ על המטופל לשתף. אפשר להתקרב לנושאים רגישים בקצב שלו, דרך משהו שמרגיש פחות מאיים."},{"id":"article-heading-1f4fe4e607d0","heading":"הכלב גם יכול לעזור לנו להירגע","text":"הכלב גם יכול לעזור לנו להירגע"},{"id":"article-paragraph-86145db44111","heading":"הכלב גם יכול לעזור לנו להירגע","text":"מעבר לקשר ולפעילות המשותפת, יש גם השפעה אפשרית של הכלב על תחושת המתח והלחץ."},{"id":"article-paragraph-ae9d77394d41","heading":"הכלב גם יכול לעזור לנו להירגע","text":"מחקרים מצאו שאינטראקציה עם כלבים עשויה להפחית תחושות של סטרס וחרדה. למשל, סקירה ומטא-אנליזה שפורסמה בשנת 2025 מצאה ירידה ברמות המתח והחרדה בקרב סטודנטים שהשתתפו בהתערבויות בעזרת כלבים."},{"id":"article-paragraph-fb16c0270827","heading":"הכלב גם יכול לעזור לנו להירגע","text":"לפעמים אפשר לראות את זה גם במפגש עצמו. מטופל שמגיע מתוח, מתיישב ליד הכלב, מלטף אותו ובהדרגה מצליח להירגע."},{"id":"article-paragraph-db4e110498cf","heading":"הכלב גם יכול לעזור לנו להירגע","text":"אבל מבחינתי, המטרה היא לא רק שהמטופל ירגיש טוב בזמן שהוא נמצא עם הכלב. המטרה היא להשתמש בחוויה הזאת כדי לעזור לו להבין מה מרגיע אותו, לזהות את הצרכים שלו ולפתח כלים שיוכל להשתמש בהם גם מחוץ לחדר הטיפולים."},{"id":"article-heading-69727beeb76f","heading":"אז מה בעצם עושים בטיפול?","text":"אז מה בעצם עושים בטיפול?"},{"id":"article-paragraph-377348ad903a","heading":"אז מה בעצם עושים בטיפול?","text":"אין שני מפגשים שנראים בדיוק אותו הדבר."},{"id":"article-paragraph-4058c8b45820","heading":"אז מה בעצם עושים בטיפול?","text":"לפעמים אנחנו משחקים עם הכלב, לפעמים מלמדים אותו משימות חדשות, לפעמים משלבים משחקים טיפוליים ולפעמים פשוט יושבים ומדברים כשהכלב נמצא לידנו."},{"id":"article-paragraph-a5898bf73eb5","heading":"אז מה בעצם עושים בטיפול?","text":"מה שחשוב הוא לא הפעילות עצמה, אלא מה שאנחנו עושים איתה."},{"id":"article-paragraph-77a33b36d9fc","heading":"אז מה בעצם עושים בטיפול?","text":"אותו משחק יכול לשמש לעבודה על ביטחון עצמי אצל מטופל אחד, על ויסות רגשי אצל מטופל אחר ועל תקשורת ושיתוף פעולה אצל מטופל שלישי."},{"id":"article-paragraph-297a7eb9cfbc","heading":"אז מה בעצם עושים בטיפול?","text":"הכול תלוי במטרות הטיפוליות, בצרכים של המטופל ובמה שעולה במהלך המפגש."},{"id":"article-paragraph-8539f4b27a23","heading":"אז מה בעצם עושים בטיפול?","text":"חשוב גם לזכור שהכלב הוא שותף לתהליך, ולא רק כלי עבודה. גם לו יש צרכים, גבולות ורצונות שחשוב לכבד. ההתייחסות הזאת בפני עצמה יכולה להפוך להזדמנות לעבודה על אמפתיה, הקשבה והתחשבות באחר."},{"id":"article-heading-1482e8bd25e1","heading":"אז האם זה באמת עובד?","text":"אז האם זה באמת עובד?"},{"id":"article-paragraph-568b8c840a81","heading":"אז האם זה באמת עובד?","text":"בשנים האחרונות מצטברים יותר מחקרים שבוחנים את התרומה של כלבים לתהליכים טיפוליים."},{"id":"article-paragraph-41adbe189bf9","heading":"אז האם זה באמת עובד?","text":"סקירות מחקריות מצביעות על פוטנציאל חיובי בתחומים כמו הפחתת מתח וחרדה, שיפור באינטראקציה חברתית ועידוד מעורבות בתהליך."},{"id":"article-paragraph-02179322c0fd","heading":"אז האם זה באמת עובד?","text":"מבחינתי, הכלב הוא לא פתרון קסם, והוא בוודאי לא מחליף את המטפל או את התהליך הטיפולי."},{"id":"article-paragraph-278cfde26b01","heading":"אז האם זה באמת עובד?","text":"אבל הוא יכול לפתוח דלתות שלפעמים קשה לפתוח באמצעות שיחה בלבד."},{"id":"article-paragraph-1c538e48c2a9","heading":"אז האם זה באמת עובד?","text":"הוא מאפשר לנו ליצור קשר, לחוות הצלחות וכישלונות, להתמודד עם תסכול, לתרגל מיומנויות ולדבר על נושאים שלא תמיד פשוט לדבר עליהם."},{"id":"article-paragraph-a20a6bdc5013","heading":"אז האם זה באמת עובד?","text":"ולפעמים, דווקא מתוך משחק פשוט עם הכלב, מתרחשת העבודה הרגשית המשמעותית ביותר."},{"id":"article-reference-6ce74fb7899d","heading":"מקורות","text":"Collier et al. (2022) סקירה שיטתית על השפעת נוכחות כלבים על הקשר הטיפולי."},{"id":"article-reference-df2a1a13067c","heading":"מקורות","text":"Sim et al. (2025) סקירה שיטתית ומטא-אנליזה על השפעת התערבויות בעזרת כלבים על מתח וחרדה בקרב סטודנטים."},{"id":"article-reference-a5d59d11cf6a","heading":"מקורות","text":"The Impact of Dog-Assisted Therapy Among Children and Adolescents with Autism Spectrum Disorder (2024) סקירה שיטתית על התערבויות בעזרת כלבים בקרב ילדים ומתבגרים על הרצף האוטיסטי."}]},{"title":"האם הכלב הוא המטפל?","url":"https://derech-hakelev.com/pages/articles/is-the-dog-the-therapist/","entries":[{"id":"article-title-406adba1f82f","heading":"תחילת המאמר","text":"האם הכלב הוא המטפל?"},{"id":"article-paragraph-5e7366581aea","heading":"פתיחת המאמר","text":"לא מעט פעמים אני נתקל באמירות כמו \"הכלב הוא המטפל האמיתי\" או \"הכלב עושה את כל העבודה\". אני יכול להבין מאיפה הן מגיעות. מי שעובד עם כלבים בטיפול מכיר את הרגעים שבהם הכלב מצליח ליצור קשר, לעורר רגש או להגיע למטופל בדרך שאנחנו כמטפלים לא תמיד מצליחים."},{"id":"article-paragraph-17724bbf8800","heading":"פתיחת המאמר","text":"אבל למרות התרומה המשמעותית של הכלב, חשוב לי להדגיש משהו: הכלב הוא לא המטפל."},{"id":"article-paragraph-107d89933c50","heading":"פתיחת המאמר","text":"הכלב הוא שותף לתהליך הטיפולי, לפעמים שותף משמעותי מאוד, אבל האחריות על התהליך, על המטרות ועל ההתערבויות נשארת אצל המטפל."},{"id":"article-paragraph-a5827b056e7b","heading":"פתיחת המאמר","text":"וההבחנה הזאת חשובה הרבה יותר ממה שאולי נדמה."},{"id":"article-heading-2a46e6d6091b","heading":"כשהכלב הופך למרכז במקום המטופל","text":"כשהכלב הופך למרכז במקום המטופל"},{"id":"article-paragraph-493e6598d77d","heading":"כשהכלב הופך למרכז במקום המטופל","text":"אחד הדברים שאני חושב שחשוב להיזהר מהם בטיפול בעזרת כלבים הוא הנטייה להתמקד יותר מדי בכלב."},{"id":"article-paragraph-a3609dca62d3","heading":"כשהכלב הופך למרכז במקום המטופל","text":"קל מאוד להישאב לזה. הרי הכלב נמצא בחדר, הוא מעורר עניין, אפשר לשחק איתו, ללמד אותו פקודות, לעשות מסלולי מכשולים ולשלב אינספור פעילויות."},{"id":"article-paragraph-4198c23db3aa","heading":"כשהכלב הופך למרכז במקום המטופל","text":"אבל האם כל פעילות כזאת היא בהכרח טיפולית?"},{"id":"article-paragraph-7ff7de299697","heading":"כשהכלב הופך למרכז במקום המטופל","text":"ממש לא."},{"id":"article-paragraph-1e7c37ba7657","heading":"כשהכלב הופך למרכז במקום המטופל","text":"נניח שמטופל מגיע עם קושי בביטחון עצמי, ואנחנו מקדישים את רוב המפגש ללימוד פקודות חדשות לכלב. יכול להיות שהוא ייהנה מאוד, ואפילו יצליח במשימה. אבל אם לא חשבנו איך הפעילות קשורה לקושי שלו, מה אנחנו רוצים לקדם באמצעותה ואיך היא משתלבת בתהליך הטיפולי, יכול להיות שבעצם העברנו שיעור אילוף מוצלח ולא מפגש טיפולי משמעותי."},{"id":"article-paragraph-a4d81b443def","heading":"כשהכלב הופך למרכז במקום המטופל","text":"וזה לא אומר שאילוף הוא לא כלי טיפולי. להפך. אני משתמש באילוף לא מעט, והוא יכול להיות כלי מצוין לעבודה על ויסות רגשי, התמדה, התמודדות עם תסכול, תקשורת וביטחון עצמי."},{"id":"article-paragraph-62907739829c","heading":"כשהכלב הופך למרכז במקום המטופל","text":"ההבדל הוא לא במה שאנחנו עושים, אלא למה אנחנו עושים את זה."},{"id":"article-paragraph-59f43fb5eefc","heading":"כשהכלב הופך למרכז במקום המטופל","text":"גם משחק פשוט עם הכלב יכול להיות התערבות טיפולית משמעותית, ולעומת זאת פעילות מורכבת ומושקעת יכולה להיות כמעט חסרת ערך טיפולי אם היא לא מותאמת לצרכים של המטופל."},{"id":"article-heading-e7b3df925980","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"לא כל דבר צריך לעבור דרך הכלב"},{"id":"article-paragraph-60b34687140e","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"אני חושב שזאת נקודה חשובה במיוחד."},{"id":"article-paragraph-015f00cb1976","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"לפעמים, דווקא בגלל שאנחנו עוסקים בטיפול בעזרת כלבים, נוצרת תחושה שצריך לשלב את הכלב בכל פעילות, בכל שיחה ובכל נושא שעולה."},{"id":"article-paragraph-af2526283ad4","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"אבל לא כל קושי צריך להפוך למשימת אילוף, ולא כל שיחה על רגשות צריכה להתחיל בשאלה \"איך לדעתך הכלב מרגיש?\"."},{"id":"article-paragraph-851c8c5427f3","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"אם מטופל משתף בחוויה משמעותית שעבר, לא תמיד נכון לחפש דרך להכניס את הכלב לשיחה. לפעמים הדבר הנכון ביותר הוא פשוט להקשיב לו, להיות איתו ולתת מקום למה שהוא מביא."},{"id":"article-paragraph-409223c461c2","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"כשאנחנו מתעקשים לשלב את הכלב גם כשאין לכך סיבה טיפולית, אנחנו עלולים להסיט את תשומת הלב מהמטופל, לפספס תכנים חשובים ואפילו לפגוע ברצף של התהליך."},{"id":"article-paragraph-0f362c365561","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"מבחינתי, הכלב צריך לשרת את התהליך הטיפולי, ולא להפך."},{"id":"article-paragraph-e03b57279584","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"זה גם אומר שלפעמים הכלב יהיה פעיל מאוד במפגש, לפעמים הוא פשוט ינוח לידנו, ולפעמים כמעט שלא נשלב אותו בכלל."},{"id":"article-paragraph-ad05aa14de14","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"וזה בסדר גמור."},{"id":"article-heading-bd10000ae735","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים"},{"id":"article-paragraph-0527c71c2829","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"אחרי כל זה, חשוב לי להדגיש גם את הצד השני."},{"id":"article-paragraph-0199909fe794","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"יש רגעים שבהם הכלב מצליח להביא לתהליך משהו שאני כמטפל לא בהכרח יכול להביא בעצמי."},{"id":"article-paragraph-b8a423e17f96","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"אני רוצה לשתף בסיפור שממחיש את זה."},{"id":"article-paragraph-204f05828d88","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"ילדה בת 11 הגיעה למפגש הראשון שלה. עוד לפני המפגש קיבלתי הודעה מאמא שלה שהילדה לא רוצה להגיע."},{"id":"article-paragraph-e96db2e68a99","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"כשהיא הגיעה עם אמא שלה, היה ברור שהיא ממש לא רוצה להיות שם. הצגתי את עצמי ואת הכלבים, פניתי אליה וניסיתי ליצור קשר, אבל אחרי שתי שאלות היא התחילה לבכות."},{"id":"article-paragraph-02ff6b8b6bfa","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"היא אמרה שהיא לא רוצה את המפגשים, שאין שום סיבה שתהיה בהם ושהיא רוצה ללכת הביתה. גם הניסיונות שלי ושל אמא שלה לעזור לה להישאר נתקלו בהתנגדות מוחלטת."},{"id":"article-paragraph-6e2540bf2c4b","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"ואז קרה משהו מעניין."},{"id":"article-paragraph-6b81214193be","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"לוגאן, הכלב שלי, ניגש אליה, עלה על ברכיה וחיבק אותה. היא התחילה ללטף אותו, ולאט לאט הבכי נרגע."},{"id":"article-paragraph-ae24fcc355cf","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"אני לא יודע מה בדיוק עבר לה בראש באותו רגע, וגם לא יכול לדעת מה לוגאן הרגיש או התכוון לעשות. אבל יכולתי לראות שמשהו באינטראקציה ביניהם השתנה. היא התחילה לדבר, סיפרה על הכלבה שלה, ובהדרגה נפתחה האפשרות להמשיך את המפגש."},{"id":"article-paragraph-11ecb9435ff3","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"בהמשך שיחקנו, דיברנו ואפילו צחקנו."},{"id":"article-paragraph-eeaf25c86966","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"בסוף המפגש אמא שלה שאלה אותה אם בשבוע הבא היא רוצה להגיע, והילדה חייכה והשיבה בחיוב."},{"id":"article-paragraph-d3a42f30ec4e","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"אני חושב שהסיפור הזה ממחיש היטב את הייחודיות של הטיפול בעזרת כלבים."},{"id":"article-paragraph-1026e2369766","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"באותו רגע, אחרי שהניסיונות שלי ליצור קשר לא הצליחו, לוגאן הצליח לאפשר משהו אחר. הוא לא שאל אותה למה היא בוכה, לא ניסה לשכנע אותה להישאר ולא ביקש ממנה להסביר מה היא מרגישה."},{"id":"article-paragraph-b1648a69553c","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"הוא פשוט יצר איתה קשר בדרך אחרת."},{"id":"article-paragraph-dbcb8d3c8b3f","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"וזה בדיוק המקום שבו הכלב יכול להיות שותף משמעותי כל כך לתהליך."},{"id":"article-heading-7868e0d97414","heading":"התפקיד שלנו הוא לדעת מה לעשות עם מה שקורה","text":"התפקיד שלנו הוא לדעת מה לעשות עם מה שקורה"},{"id":"article-paragraph-a4c77ee557af","heading":"התפקיד שלנו הוא לדעת מה לעשות עם מה שקורה","text":"אבל גם בסיפור הזה, לוגאן לא החליף את התהליך הטיפולי."},{"id":"article-paragraph-a76265a73b9b","heading":"התפקיד שלנו הוא לדעת מה לעשות עם מה שקורה","text":"הקשר שנוצר איתו אפשר לנו להתחיל לבנות קשר, להפחית את ההתנגדות הראשונית וליצור חוויה אחרת מזאת שהילדה ציפתה לה."},{"id":"article-paragraph-9c9a9663faf1","heading":"התפקיד שלנו הוא לדעת מה לעשות עם מה שקורה","text":"מכאן התפקיד שלי כמטפל היה להמשיך את העבודה, להבין את הקשיים שלה, לבנות איתה קשר טיפולי ולחשוב איך אפשר להשתמש בחוויות שנוצרות במפגשים כדי לקדם את המטרות שלה."},{"id":"article-paragraph-a3ea9163a479","heading":"התפקיד שלנו הוא לדעת מה לעשות עם מה שקורה","text":"לפעמים ההתערבות הנכונה היא ליזום פעילות עם הכלב, לפעמים לעזור למטופל לעבד חוויה שהתרחשה איתו, ולפעמים דווקא לדעת מתי לא להתערב ולתת לקשר ביניהם להתפתח."},{"id":"article-paragraph-717c9fb90112","heading":"התפקיד שלנו הוא לדעת מה לעשות עם מה שקורה","text":"חשוב גם לזכור שלא כל התנהגות של הכלב היא בהכרח התערבות טיפולית. כלבים הם בעלי חיים עם צרכים, רצונות ותגובות משלהם. לא כל פעולה שלהם נושאת משמעות רגשית עמוקה, ולא צריך לנסות למצוא משמעות כזאת בכל דבר."},{"id":"article-heading-c6084dadd67d","heading":"אז מה הופך את המפגש לטיפולי?","text":"אז מה הופך את המפגש לטיפולי?"},{"id":"article-paragraph-868bd88c17f3","heading":"אז מה הופך את המפגש לטיפולי?","text":"בעיניי, השאלה החשובה היא לא כמה הכלב השתתף במפגש, כמה פקודות המטופל הצליח ללמד אותו או כמה פעילויות הספקנו לעשות."},{"id":"article-paragraph-32406a86289d","heading":"אז מה הופך את המפגש לטיפולי?","text":"השאלה היא מה קרה למטופל במהלך המפגש, ואיך הדברים שהתרחשו בו יכולים לעזור לו גם מחוץ לחדר הטיפולים."},{"id":"article-paragraph-fd29e4153c50","heading":"אז מה הופך את המפגש לטיפולי?","text":"האם הוא הצליח להתמודד עם תסכול? האם התנסה בהצבת גבולות? האם הרגיש בטוח מספיק כדי לשתף? האם הצליח לזהות משהו חדש על עצמו?"},{"id":"article-paragraph-0e1b7425caea","heading":"אז מה הופך את המפגש לטיפולי?","text":"ולפעמים, האם פשוט הצלחנו ליצור קשר במקום שבו קודם הייתה התנגדות?"},{"id":"article-paragraph-0063e1eb0d1e","heading":"אז מה הופך את המפגש לטיפולי?","text":"אני מאמין שהייחודיות של טיפול בעזרת כלבים נמצאת בשילוב בין הידע והחשיבה המקצועית של המטפל לבין האפשרויות שהכלב מביא איתו."},{"id":"article-paragraph-a80ce99992b1","heading":"אז מה הופך את המפגש לטיפולי?","text":"הכלב לא צריך להיות במרכז המפגש כדי להיות משמעותי בו."},{"id":"article-paragraph-04bff0bae08c","heading":"אז מה הופך את המפגש לטיפולי?","text":"המטופל הוא זה שצריך להיות במרכז. תמיד."},{"id":"article-paragraph-2ed452510569","heading":"אז מה הופך את המפגש לטיפולי?","text":"והכלב? הוא יכול להיות שותף נפלא בדרך לשם."}]},{"title":"הגישה ההתפתחותית-היקשרותית בטיפול בעזרת כלבים","url":"https://derech-hakelev.com/pages/articles/developmental-attachment-dog-therapy/","entries":[{"id":"article-title-72382359eb2d","heading":"תחילת המאמר","text":"הגישה ההתפתחותית-היקשרותית בטיפול בעזרת כלבים"},{"id":"article-paragraph-6566d490308f","heading":"פתיחת המאמר","text":"למה ילד מגיב בתוקפנות כשמשהו לא מצליח לו? למה דווקא כשהוא זקוק לעזרה, הוא מתנגד לכל ניסיון לעזור לו? ולמה לפעמים, ככל שאנחנו מנסים ללמד ילד לשלוט בעצמו, כך ההתנגדות שלו רק גוברת?"},{"id":"article-paragraph-54a80b956b39","heading":"פתיחת המאמר","text":"בעבודה הטיפולית אנחנו פוגשים לא מעט התנהגויות מאתגרות. הנטייה הטבעית היא לנסות לשנות אותן: ללמד את הילד לווסת את עצמו, להתמודד עם תסכול, לשתף פעולה או להגיב אחרת."},{"id":"article-paragraph-ea38e9b1218b","heading":"פתיחת המאמר","text":"אבל הגישה ההתפתחותית-היקשרותית מציעה לנו להסתכל על הדברים מזווית קצת אחרת."},{"id":"article-paragraph-3c3c998ff316","heading":"פתיחת המאמר","text":"במקום לשאול רק איך משנים את ההתנהגות, היא מזמינה אותנו לשאול מה עומד מאחוריה, מה הילד צריך ומה יכול לעזור לו להתפתח."},{"id":"article-heading-0c36425ca7b1","heading":"מהי הגישה ההתפתחותית-היקשרותית?","text":"מהי הגישה ההתפתחותית-היקשרותית?"},{"id":"article-paragraph-7854180b8f93","heading":"מהי הגישה ההתפתחותית-היקשרותית?","text":"הגישה ההתפתחותית-היקשרותית, המזוהה בין היתר עם הפסיכולוג הקנדי ד\"ר גורדון ניופלד, נשענת על תיאוריות של התקשרות, התפתחות רגשית ותהליכי הבשלה."},{"id":"article-paragraph-9470c3adce76","heading":"מהי הגישה ההתפתחותית-היקשרותית?","text":"בבסיס הגישה עומדת ההבנה שהתפתחות רגשית היא לא רק עניין של למידת מיומנויות. היא גם תהליך של הבשלה, שמתרחש כאשר מתקיימים התנאים המתאימים."},{"id":"article-paragraph-ffdb893f3722","heading":"מהי הגישה ההתפתחותית-היקשרותית?","text":"אחד התנאים החשובים ביותר הוא תחושת ביטחון בתוך קשר."},{"id":"article-paragraph-ff5eee9b6c83","heading":"מהי הגישה ההתפתחותית-היקשרותית?","text":"כשילד מרגיש שיש מבוגר שאפשר לסמוך עליו, שמבין אותו ושנמצא לצידו גם כשהוא מתקשה, מתאפשר לו בהדרגה להתמודד עם רגשות מורכבים, לחקור, להתנסות ולפתח עצמאות."},{"id":"article-paragraph-bdda9f111692","heading":"מהי הגישה ההתפתחותית-היקשרותית?","text":"זה לא אומר שאין מקום לגבולות, להכוונה או ללמידה. אלא שהקשר והביטחון הם הבסיס שעליו אפשר לבנות את כל אלה."},{"id":"article-paragraph-a339b8475115","heading":"מהי הגישה ההתפתחותית-היקשרותית?","text":"בגישה הזאת אנחנו גם מנסים להבין את ההתנהגות כביטוי אפשרי למשהו עמוק יותר. למשל, מאחורי התפרצות כעס יכולים להסתתר תסכול, פחד, פגיעות או קושי להתמודד עם מציאות שלא תואמת את הרצונות שלנו."},{"id":"article-paragraph-7eaa0a7f71fd","heading":"מהי הגישה ההתפתחותית-היקשרותית?","text":"המטרה היא לא להצדיק כל התנהגות, אלא להבין אותה טוב יותר כדי שנוכל להגיב אליה בצורה שתסייע להתפתחות."},{"id":"article-heading-eddf2c343ecf","heading":"קודם הקשר, אחר כך העבודה","text":"קודם הקשר, אחר כך העבודה"},{"id":"article-paragraph-588f6784c7a8","heading":"קודם הקשר, אחר כך העבודה","text":"אחד הדברים שאני מתחבר אליהם בגישה הזאת הוא החשיבות שהיא נותנת לקשר."},{"id":"article-paragraph-bcbbd12b6c27","heading":"קודם הקשר, אחר כך העבודה","text":"לפעמים אנחנו ממהרים להתחיל לעבוד על המטרות הטיפוליות: ויסות רגשי, דחיית סיפוקים, הצבת גבולות או ביטחון עצמי."},{"id":"article-paragraph-6d136abb64a9","heading":"קודם הקשר, אחר כך העבודה","text":"אבל מה קורה כשהמטופל עדיין לא מרגיש בטוח איתנו? כשהוא חושש להיכשל, מתקשה לתת אמון או בכלל לא רוצה להיות בטיפול?"},{"id":"article-paragraph-1c744f837fff","heading":"קודם הקשר, אחר כך העבודה","text":"כאן בדיוק נכנס אחד היתרונות המשמעותיים של הטיפול בעזרת כלבים."},{"id":"article-paragraph-7eead00c4b25","heading":"קודם הקשר, אחר כך העבודה","text":"הכלב יכול לעזור לנו ליצור קשר בצורה טבעית יותר. במקום להתחיל בשאלות או בניסיון לדבר על הקשיים, אפשר להתחיל במשחק משותף, בליטוף או בפעילות עם הכלב."},{"id":"article-paragraph-06f4d6c06be7","heading":"קודם הקשר, אחר כך העבודה","text":"המפגש עשוי להפוך לפחות מאיים, והמטופל לא מרגיש שכל תשומת הלב מופנית אליו."},{"id":"article-paragraph-f23dafbcd334","heading":"קודם הקשר, אחר כך העבודה","text":"לפעמים הקשר עם הכלב הוא זה שמאפשר את הצעד הראשון לקראת הקשר עם המטפל."},{"id":"article-paragraph-48a827ff1591","heading":"קודם הקשר, אחר כך העבודה","text":"חשוב לי להדגיש שהכלב לא מחליף את הקשר הטיפולי. להפך, אנחנו רוצים להיעזר בקשר שנוצר איתו כדי לבנות בהדרגה גם את הקשר בין המטפל למטופל."},{"id":"article-heading-0503e77809c7","heading":"משחק הוא הרבה יותר ממשחק","text":"משחק הוא הרבה יותר ממשחק"},{"id":"article-paragraph-75250b6ce95c","heading":"משחק הוא הרבה יותר ממשחק","text":"בגישה ההתפתחותית-היקשרותית יש מקום משמעותי למשחק."},{"id":"article-paragraph-014b934c4696","heading":"משחק הוא הרבה יותר ממשחק","text":"משחק מאפשר לנו להתנסות ברגשות, בתפקידים ובמצבים שונים, בלי שנצטרך להתמודד עם כל ההשלכות שלהם במציאות."},{"id":"article-paragraph-5543eaa24039","heading":"משחק הוא הרבה יותר ממשחק","text":"דרך משחק אפשר לפגוש תסכול, פחד, תחרות, אכזבה, הצלחה וכישלון, בסביבה שבה יש מקום לטעות, לנסות שוב ולגלות דברים חדשים."},{"id":"article-paragraph-0e58257c73f7","heading":"משחק הוא הרבה יותר ממשחק","text":"וזה מתחבר מאוד לעבודה עם כלבים."},{"id":"article-paragraph-1ab78bcc399c","heading":"משחק הוא הרבה יותר ממשחק","text":"למשל, ילד שמתקשה להתמודד עם תסכול יכול להשתתף במשחק שבו הוא צריך להוביל את הכלב במסלול מסוים. הכלב לא תמיד יפעל בדיוק כפי שהילד רוצה, ולפעמים המשימה לא תצליח."},{"id":"article-paragraph-ec2c6bf44626","heading":"משחק הוא הרבה יותר ממשחק","text":"אפשר כמובן להפוך את הרגע הזה לשיעור על סבלנות או שליטה בכעסים. אבל אפשר גם להסתכל עליו אחרת."},{"id":"article-paragraph-dc8bc0fe117b","heading":"משחק הוא הרבה יותר ממשחק","text":"אולי הילד כרגע מוצף מדי מכדי ללמוד משהו? אולי הוא צריך קודם כול שנעזור לו להתמודד עם האכזבה? ואולי דווקא משחקיות, הומור או שינוי קטן במשימה יאפשרו לו להמשיך בלי להרגיש שהוא נכשל?"},{"id":"article-paragraph-896fc3ee8e7f","heading":"משחק הוא הרבה יותר ממשחק","text":"במקום להתמקד רק בהתנהגות שאנחנו רוצים לשנות, אנחנו מנסים להבין מה הילד מסוגל לשאת באותו רגע ומה יכול לעזור לו להתקדם."},{"id":"article-heading-263c4c9c5195","heading":"לא כל התנגדות היא בעיית משמעת","text":"לא כל התנגדות היא בעיית משמעת"},{"id":"article-paragraph-c7acab418b4f","heading":"לא כל התנגדות היא בעיית משמעת","text":"אחד המושגים המעניינים בגישה של ניופלד הוא רצון נגדי (Counterwill), שמתאר נטייה טבעית להתנגד כשאנחנו מרגישים שמישהו אחר מנסה לכפות עלינו את רצונו."},{"id":"article-paragraph-89be02364eb8","heading":"לא כל התנגדות היא בעיית משמעת","text":"לפעמים ילד מתנגד לא בגלל שהוא לא רוצה להשתתף או לא מסוגל לעשות את מה שמבקשים ממנו, אלא דווקא משום שהוא מרגיש שמנסים להפעיל עליו לחץ או לקחת ממנו את השליטה."},{"id":"article-paragraph-57ecd71d4a98","heading":"לא כל התנגדות היא בעיית משמעת","text":"אני נזכר בילדה בת 6 שטיפלתי בה. כבר מהמפגשים הראשונים היא הייתה משתלטת על המפגש, וכל ניסיון שלי להוביל או להציע פעילות נתקל בהתנגדות. לאורך תקופה ניסיתי לאתגר את המקום הזה, מתוך מחשבה שהיא צריכה ללמוד להתמודד גם עם מצבים שבהם היא לא זאת שמחליטה."},{"id":"article-paragraph-f6ceb30812cf","heading":"לא כל התנגדות היא בעיית משמעת","text":"אבל ככל שניסיתי להוביל, כך היא התרחקה מהתהליך."},{"id":"article-paragraph-2491ea3c1b9d","heading":"לא כל התנגדות היא בעיית משמעת","text":"באחד המפגשים החלטתי לנסות משהו אחר. אמרתי לה שהיום היא מחליטה הכול. אני לא שואל שאלות ולא בוחר מה עושים. היא קובעת."},{"id":"article-paragraph-1c3c08b5dd1d","heading":"לא כל התנגדות היא בעיית משמעת","text":"בהתחלה היא הייתה מבולבלת ואפילו שאלה למה. אבל אחרי שהבינה שאני רציני, היא התחילה לחייך, בחרה משחק והכריזה שנשחק \"המלך אמר\" (אפרופו ענייני שליטה)."},{"id":"article-paragraph-cf6ce5829283","heading":"לא כל התנגדות היא בעיית משמעת","text":"תוך כדי המשחק קרה משהו מעניין. בלי שביקשתי, היא התחילה לספר לי על השבוע שלה, ואפילו ביקשה לעבוד עם הכלבים. דברים שקודם היה קשה להגיע אליהם התחילו לקרות באופן טבעי."},{"id":"article-paragraph-ae72af0683b2","heading":"לא כל התנגדות היא בעיית משמעת","text":"זה היה אחד המפגשים המשמעותיים שהיו לנו. דווקא כשוויתרתי על הניסיון להוביל את המפגש, נוצר יותר מקום לקשר ולשיתוף פעולה."},{"id":"article-paragraph-cf867b21889a","heading":"לא כל התנגדות היא בעיית משמעת","text":"במפגש שאחריו היא כבר אמרה לי: \"גם היום אני רוצה להחליט\". וכשהגיע הזמן לבחור משחק, היא הוסיפה: \"אני רוצה שאתה תבחר\"."},{"id":"article-paragraph-6f8a844c5e3f","heading":"לא כל התנגדות היא בעיית משמעת","text":"היא לא ויתרה על הצורך שלה בשליטה כי דרשתי ממנה לעשות את זה. היא הצליחה לשחרר קצת ממנו דווקא כשהרגישה שהבחירה נמצאת בידיים שלה."},{"id":"article-paragraph-d51ec5aa2837","heading":"לא כל התנגדות היא בעיית משמעת","text":"כמובן, לא כל התנגדות היא בהכרח רצון נגדי. לפעמים היא נובעת מחרדה, מקושי בוויסות, מחוסר אמון או מצרכים אחרים. אבל הסיפור הזה מזכיר לי כמה חשוב לא למהר להיאבק בהתנגדות, אלא לנסות להבין מה עומד מאחוריה."},{"id":"article-paragraph-098fe35c7446","heading":"לא כל התנגדות היא בעיית משמעת","text":"בטיפול בעזרת כלבים יש לנו הרבה אפשרויות לעשות את זה דרך משחק, בחירה והתנסות משותפת, בלי שכל דבר יהפוך לדרישה או למשימה שצריך לבצע."},{"id":"article-heading-b41151e81947","heading":"גם לתסכול ולעצב יש מקום","text":"גם לתסכול ולעצב יש מקום"},{"id":"article-paragraph-c124dcb0bad6","heading":"גם לתסכול ולעצב יש מקום","text":"בעבודה טיפולית אנחנו רוצים לעזור למטופלים להתמודד טוב יותר עם רגשות קשים. אבל לא תמיד המטרה היא להעלים את הרגש או להפסיק אותו במהירות."},{"id":"article-paragraph-c4f1679dc220","heading":"גם לתסכול ולעצב יש מקום","text":"בגישה ההתפתחותית-היקשרותית יש חשיבות ליכולת לפגוש גם רגשות פגיעים, כמו עצב, אכזבה וחוסר אונים, במקום להישאר רק עם הכעס או ההתנגדות שמופיעים כלפי חוץ."},{"id":"article-paragraph-c2bda6b33b76","heading":"גם לתסכול ולעצב יש מקום","text":"למשל, ילד שמנסה שוב ושוב להצליח במשימה עם הכלב ולא מצליח, עלול להתפרץ בכעס ולהאשים את הכלב."},{"id":"article-paragraph-c2015a5f0fad","heading":"גם לתסכול ולעצב יש מקום","text":"אפשר לעבוד איתו על הדרך שבה הוא מבטא את הכעס, וזה בהחלט חשוב."},{"id":"article-paragraph-be6e32039337","heading":"גם לתסכול ולעצב יש מקום","text":"אבל אפשר גם לנסות להבין מה יש מתחת לכעס הזה. אולי הוא מאוד רצה להצליח? אולי קשה לו להרגיש שהוא לא מסוגל? אולי הוא מאוכזב מעצמו?"},{"id":"article-paragraph-0d0a1596007f","heading":"גם לתסכול ולעצב יש מקום","text":"לפעמים, כשהילד מצליח לפגוש את האכזבה ולקבל אותה בתוך קשר בטוח, מתאפשרת גם תגובה גמישה יותר."},{"id":"article-paragraph-43cb2dc35cc6","heading":"גם לתסכול ולעצב יש מקום","text":"התפקיד שלנו הוא לא למנוע כל תסכול, אלא לעזור למטופל לפגוש אותו בלי להישאר איתו לבד."},{"id":"article-heading-4e7bb288c889","heading":"ומה לגבי הקשר עם הכלב עצמו?","text":"ומה לגבי הקשר עם הכלב עצמו?"},{"id":"article-paragraph-10517a6fdcf5","heading":"ומה לגבי הקשר עם הכלב עצמו?","text":"הקשר עם הכלב יכול להפוך לחלק משמעותי מאוד מהתהליך."},{"id":"article-paragraph-068cc7575c5d","heading":"ומה לגבי הקשר עם הכלב עצמו?","text":"יש מטופלים שמרגישים בנוח יותר להביע חיבה כלפי הכלב, להתקרב אליו או לשתף אותו במה שעובר עליהם."},{"id":"article-paragraph-9c1ebf83f586","heading":"ומה לגבי הקשר עם הכלב עצמו?","text":"אפשר להיעזר בקשר הזה כדי לעבוד על אמון, קרבה, גבולות, אמפתיה ותחושת ביטחון."},{"id":"article-paragraph-c9d3075120a0","heading":"ומה לגבי הקשר עם הכלב עצמו?","text":"אבל חשוב להבחין בין קשר משמעותי עם כלב לבין התקשרות בטוחה עם דמות אנושית. אלה לא בהכרח אותם דברים."},{"id":"article-paragraph-891288fdc53b","heading":"ומה לגבי הקשר עם הכלב עצמו?","text":"הכלב יכול להיות מקור לנחמה ולקרבה, אבל הוא לא מחליף את הצורך בקשרים אנושיים משמעותיים."},{"id":"article-paragraph-7675336b538a","heading":"ומה לגבי הקשר עם הכלב עצמו?","text":"מבחינתי, המטרה היא לא שהמטופל יהיה תלוי בכלב כדי להרגיש בטוח, אלא שהקשר איתו יסייע לנו ליצור חוויות שאפשר יהיה בהמשך להרחיב גם לקשרים ולמצבים אחרים בחיים."},{"id":"article-paragraph-f468ca01bdac","heading":"ומה לגבי הקשר עם הכלב עצמו?","text":"יש גם חשיבות לדרך שבה אנחנו מתייחסים לכלב. כשאנחנו מכבדים את הצרכים שלו, מזהים מתי הוא רוצה להתקרב ומתי הוא זקוק למרחב, אנחנו מדגימים קשר שיש בו הקשבה, התחשבות וגבולות."},{"id":"article-heading-640d560d29fa","heading":"אז מה זה משנה בפועל?","text":"אז מה זה משנה בפועל?"},{"id":"article-paragraph-7e0fca17591d","heading":"אז מה זה משנה בפועל?","text":"הגישה ההתפתחותית-היקשרותית לא בהכרח משנה את הפעילויות שאנחנו עושים בטיפול, אלא בעיקר את הדרך שבה אנחנו מבינים אותן ואת המטרות שאנחנו מנסים לקדם."},{"id":"article-paragraph-f252c871fffa","heading":"אז מה זה משנה בפועל?","text":"אפשר להשתמש באותו משחק עם הכלב כדי ללמד ילד לחכות לתורו, אבל אפשר גם להשתמש בו כדי להבין למה כל כך קשה לו לחכות, מה קורה לו כשהוא מאבד שליטה ואיך אפשר לעזור לו לשאת את התסכול."},{"id":"article-paragraph-d1641e07ef38","heading":"אז מה זה משנה בפועל?","text":"אפשר להתמקד בכך שהילד יבצע משימה בהצלחה, ואפשר להתמקד בכך שהוא ירגיש מספיק בטוח כדי לנסות, גם אם לא יצליח."},{"id":"article-paragraph-cee37c5e00f0","heading":"אז מה זה משנה בפועל?","text":"שתי האפשרויות לא בהכרח סותרות זו את זו. השאלה היא מה המטופל צריך באותו שלב של התהליך."},{"id":"article-paragraph-83e35a44ef09","heading":"אז מה זה משנה בפועל?","text":"חשוב גם לזכור שלא כל קושי נובע מבעיה בהתקשרות, ולא כל מטופל זקוק לאותה התערבות. לפעמים יש צורך בלמידת מיומנויות מפורשת, בהדרכה התנהגותית או בהתערבויות נוספות. ההסתכלות ההתפתחותית יכולה להשתלב בהן ולעזור לנו להבין מתי ואיך נכון להשתמש בהן."},{"id":"article-heading-6c042377fbb2","heading":"לא רק לשנות התנהגות, אלא לאפשר התפתחות","text":"לא רק לשנות התנהגות, אלא לאפשר התפתחות"},{"id":"article-paragraph-6aae42f139e1","heading":"לא רק לשנות התנהגות, אלא לאפשר התפתחות","text":"אני חושב שאחד החיבורים המשמעותיים בין הגישה ההתפתחותית-היקשרותית לטיפול בעזרת כלבים הוא ההבנה שלא כל שינוי צריך להתחיל בדרישה להשתנות."},{"id":"article-paragraph-cc316399fe2f","heading":"לא רק לשנות התנהגות, אלא לאפשר התפתחות","text":"לפעמים הוא מתחיל דווקא בתחושת ביטחון, בקשר שנוצר, במשחק משותף או בחוויה שבה מותר לנו לטעות ולהיות מי שאנחנו."},{"id":"article-paragraph-8e9f30793e20","heading":"לא רק לשנות התנהגות, אלא לאפשר התפתחות","text":"הכלב יכול לעזור לנו ליצור את התנאים האלה. הוא מאפשר מפגש פחות פורמלי, מזמין למשחק ולהתנסות, ולעיתים מצליח לעורר קרבה גם במקומות שבהם שיחה ישירה פחות מתאימה."},{"id":"article-paragraph-2aac902f38b9","heading":"לא רק לשנות התנהגות, אלא לאפשר התפתחות","text":"אבל הכלב הוא לא זה שאחראי להתפתחות, וגם לא כל פעילות איתו מקדמת אותה באופן אוטומטי."},{"id":"article-paragraph-f37141b4fda8","heading":"לא רק לשנות התנהגות, אלא לאפשר התפתחות","text":"התפקיד שלנו כמטפלים הוא להבין את האדם שמולנו, לזהות את הצרכים שלו וליצור עבורו סביבה שבה הוא יוכל להרגיש בטוח, להתנסות ולהתפתח."},{"id":"article-paragraph-6a68aa5e5656","heading":"לא רק לשנות התנהגות, אלא לאפשר התפתחות","text":"כי לפעמים, לפני שאנחנו מנסים ללמד אדם להתמודד אחרת, אנחנו צריכים קודם כול לאפשר לו להרגיש מספיק בטוח כדי להתמודד."},{"id":"article-reference-0856710187ea","heading":"מקורות","text":"Gordon Neufeld – The Attachment-Based Developmental Approach. הסבר על עקרונות הגישה ההתפתחותית-היקשרותית."},{"id":"article-reference-7f3fe1e96804","heading":"מקורות","text":"Neufeld Institute – Play & Attachment. על תפקיד המשחק ביצירת קשר ובהתפתחות."},{"id":"article-reference-20828ac19596","heading":"מקורות","text":"Zilcha-Mano, Mikulincer & Shaver (2011) Pet in the Therapy Room: An Attachment Perspective on Animal-Assisted Therapy. מאמר תיאורטי המציע מסגרת להבנת טיפול בעזרת בעלי חיים דרך תיאוריית ההתקשרות."},{"id":"article-reference-ecb359c29924","heading":"מקורות","text":"Bowlby, J. (1988) A Secure Base: Parent-Child Attachment and Healthy Human Development. ספר יסוד על התקשרות וביטחון כבסיס להתפתחות."}]},{"title":"ויסות רגשי אצל ילדים - איך טיפול בעזרת כלבים יכול לעזור?","url":"https://derech-hakelev.com/pages/articles/emotional-regulation-children-dog-therapy/","entries":[{"id":"article-title-b285b2411636","heading":"תחילת המאמר","text":"ויסות רגשי אצל ילדים - איך טיפול בעזרת כלבים יכול לעזור?"},{"id":"article-paragraph-d0ad13e1a760","heading":"פתיחת המאמר","text":"הילד מתפרץ כשמשהו לא מסתדר כמו שרצה? מתקשה להפסיד במשחק? מגיב בעוצמה גדולה לתסכול או לאכזבה? לפעמים אפילו דבר קטן יכול להוביל לבכי, לכעס או להתפרצות שנראית לא פרופורציונלית למצב."},{"id":"article-paragraph-e281ee9b19e3","heading":"פתיחת המאמר","text":"לא מעט הורים מתמודדים עם מצבים כאלה. אחד הדברים המתסכלים הוא שלפעמים הילד דווקא יודע להסביר מה היה צריך לעשות אחרת. הוא יודע שלא כדאי לצעוק, להרביץ או לזרוק דברים. ובכל זאת, ברגע האמת, כשהרגש מציף אותו, הוא מתקשה לפעול אחרת."},{"id":"article-paragraph-e0a9763feb1c","heading":"פתיחת המאמר","text":"זה אחד הדברים המשמעותיים בעבודה על ויסות רגשי אצל ילדים: הפער שבין הידיעה מה נכון לעשות לבין היכולת לעשות זאת בזמן אמת."},{"id":"article-paragraph-33e69ae78308","heading":"פתיחת המאמר","text":"בטיפול רגשי בעזרת כלבים אפשר לעבוד על הפער הזה בדרך חווייתית, דרך משחק, קשר והתנסויות שמזמנות רגשות אמיתיים בתוך מרחב טיפולי בטוח."},{"id":"article-heading-dab27643f2d0","heading":"מה זה ויסות רגשי אצל ילדים?","text":"מה זה ויסות רגשי אצל ילדים?"},{"id":"article-paragraph-5bd7268a89e7","heading":"מה זה ויסות רגשי אצל ילדים?","text":"ויסות רגשי הוא היכולת לזהות רגשות, להתמודד איתם ולהשפיע על הדרך שבה אנחנו מגיבים להם."},{"id":"article-paragraph-571219a87ab0","heading":"מה זה ויסות רגשי אצל ילדים?","text":"חשוב לי להדגיש שוויסות רגשי לא אומר להיות רגועים כל הזמן. ילד שמצליח לווסת את רגשותיו הוא לא ילד שלא כועס, לא בוכה או לא מתוסכל."},{"id":"article-paragraph-eff593995fa7","heading":"מה זה ויסות רגשי אצל ילדים?","text":"לכעס, לפחד, לתסכול ולאכזבה יש מקום חשוב בחיים שלנו. המטרה היא לא להעלים אותם, אלא לפתח את היכולת לשאת אותם ולהתמודד איתם."},{"id":"article-paragraph-60c27ebf4e5d","heading":"מה זה ויסות רגשי אצל ילדים?","text":"לדוגמה, ילד יכול לכעוס מאוד כשהוא מפסיד במשחק, ועדיין להצליח להישאר במשחק. הוא יכול להיעלב מחבר מבלי להגיב באלימות, או להתאכזב כשמשהו לא מצליח ולמצוא את הכוחות לנסות שוב."},{"id":"article-paragraph-5e924579d40a","heading":"מה זה ויסות רגשי אצל ילדים?","text":"היכולות האלה מתפתחות בהדרגה. ילדים לא נולדים עם יכולת מלאה לווסת את רגשותיהם, והם זקוקים למבוגרים שיעזרו להם לעשות זאת."},{"id":"article-paragraph-cd8b58671591","heading":"מה זה ויסות רגשי אצל ילדים?","text":"לכן, כשילד מתקשה להתמודד עם הרגשות שלו, לא תמיד מדובר בבחירה להתנהג בצורה מסוימת. לפעמים היכולת הנדרשת ממנו עדיין נמצאת בתהליך התפתחות."},{"id":"article-heading-623109c655e7","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"איך נראים קשיי ויסות רגשי אצל ילדים?"},{"id":"article-paragraph-4eba88c5241a","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"קשיים בוויסות רגשי יכולים להתבטא בדרכים שונות."},{"id":"article-paragraph-1036b31aa14b","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"יש ילדים שמגיבים בתוקפנות או בהתפרצויות זעם, ואחרים דווקא מתכנסים בתוך עצמם, נמנעים מהתמודדויות או מתקשים לשתף במה שהם מרגישים."},{"id":"article-paragraph-969fe496023f","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"הקשיים יכולים לבוא לידי ביטוי במצבים כמו:"},{"id":"article-item-3b94fab79712","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"התפרצויות כעס בעקבות הצבת גבולות או קבלת תשובה שלילית."},{"id":"article-item-1a605867aef7","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"קושי להפסיד במשחק או להתמודד עם כישלון."},{"id":"article-item-a63b4e2dad24","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"תגובות רגשיות עוצמתיות לשינויים בלתי צפויים."},{"id":"article-item-5be854ec9c31","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"קושי לחכות לתור, לדחות סיפוקים או להתאפק."},{"id":"article-item-74198f69d13a","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"קושי להירגע גם לאחר שהאירוע הסתיים."},{"id":"article-item-5508fedd4b57","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"הימנעות מהתנסויות חדשות מתוך פחד להיכשל."},{"id":"article-paragraph-7d44513903e3","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"חשוב לזכור שלא כל התפרצות מעידה על בעיה בוויסות הרגשי. ילדים חווים כעס ותסכול כחלק מההתפתחות הטבעית שלהם. השאלה היא עד כמה הקושי חוזר על עצמו, עד כמה הוא עוצמתי וכיצד הוא משפיע על התפקוד ועל מערכות היחסים של הילד."},{"id":"article-heading-53a5e290707b","heading":"איך טיפול רגשי בעזרת כלבים יכול לעזור?","text":"איך טיפול רגשי בעזרת כלבים יכול לעזור?"},{"id":"article-paragraph-8ac6ae2060c9","heading":"איך טיפול רגשי בעזרת כלבים יכול לעזור?","text":"אחד הדברים שאני אוהב בעבודה הטיפולית עם כלבים הוא שהרבה פעמים אנחנו לא צריכים ליצור באופן מלאכותי סיטואציה כדי לעבוד על קושי רגשי. הסיטואציות נוצרות מתוך הפעילות המשותפת."},{"id":"article-paragraph-ed510b5fc7f6","heading":"איך טיפול רגשי בעזרת כלבים יכול לעזור?","text":"נניח שילד מנסה ללמד את הכלב לבצע תרגיל מסוים. הוא מבקש ממנו לשבת, לעבור במסלול או לבצע משימה אחרת, אבל הכלב לא משתף פעולה כפי שציפה."},{"id":"article-paragraph-5e6a079639a2","heading":"איך טיפול רגשי בעזרת כלבים יכול לעזור?","text":"אולי הילד ינסה שוב בסבלנות. אולי יתעצבן, ירים את הקול או יחליט שהוא לא רוצה להמשיך."},{"id":"article-paragraph-1e0521c00bfd","heading":"איך טיפול רגשי בעזרת כלבים יכול לעזור?","text":"מבחוץ זו יכולה להיראות כמו פעילות פשוטה עם כלב, אבל מבחינה טיפולית מתרחש כאן משהו משמעותי."},{"id":"article-paragraph-4dc89d53d501","heading":"איך טיפול רגשי בעזרת כלבים יכול לעזור?","text":"הילד פוגש תסכול אמיתי."},{"id":"article-paragraph-77e63c60c3af","heading":"איך טיפול רגשי בעזרת כלבים יכול לעזור?","text":"עכשיו אפשר להתבונן יחד במה שקרה. מה הוא הרגיש כשהכלב לא עשה את מה שביקש? מה הוא רצה לעשות באותו רגע? האם הוא מסוגל לנסות שוב, לשנות את הדרך שבה פנה לכלב או להיעזר בי?"},{"id":"article-paragraph-fbddcab56605","heading":"איך טיפול רגשי בעזרת כלבים יכול לעזור?","text":"העבודה היא לא על כך שהכלב יבצע את התרגיל, אלא על מה שהילד עובר בדרך."},{"id":"article-heading-82d9b826d0bd","heading":"לעבוד על תסכול בלי לנסות למנוע אותו","text":"לעבוד על תסכול בלי לנסות למנוע אותו"},{"id":"article-paragraph-10dc5bde15c0","heading":"לעבוד על תסכול בלי לנסות למנוע אותו","text":"הרבה פעמים אנחנו רוצים לחסוך מילדים תסכול. אנחנו מנסים לעזור להם להצליח, למנוע מהם להפסיד או לפתור עבורם בעיות לפני שיתאכזבו."},{"id":"article-paragraph-c2e39082eadc","heading":"לעבוד על תסכול בלי לנסות למנוע אותו","text":"זה מובן, אבל היכולת להתמודד עם תסכול מתפתחת גם דרך ההתנסות בו, כשהילד מקבל תמיכה שמתאימה ליכולות שלו."},{"id":"article-paragraph-69baa9fcc962","heading":"לעבוד על תסכול בלי לנסות למנוע אותו","text":"בטיפול בעזרת כלבים יש הרבה הזדמנויות כאלה."},{"id":"article-paragraph-b434f469d676","heading":"לעבוד על תסכול בלי לנסות למנוע אותו","text":"לא כל משימה מצליחה בניסיון הראשון. לפעמים הכלב בוחר לעשות משהו אחר, לפעמים צריך לחכות, ולפעמים צריך לשנות את התוכנית."},{"id":"article-paragraph-264b28b86ee8","heading":"לעבוד על תסכול בלי לנסות למנוע אותו","text":"המטרה שלי היא לא לגרום לילד להתעצבן בכוונה, וגם לא להציף אותו מעבר למה שהוא מסוגל לשאת. המטרה היא לאפשר לו להתמודד עם אתגרים מתאימים, וללוות אותו בתוכם."},{"id":"article-paragraph-ee89b6098589","heading":"לעבוד על תסכול בלי לנסות למנוע אותו","text":"לפעמים ההישג המשמעותי ביותר במפגש הוא לא שהילד הצליח במשימה, אלא שהוא התאכזב, כעס, הצליח להתמודד עם הרגש ובחר לנסות שוב."},{"id":"article-heading-21b039df974e","heading":"ללמוד לזהות את הרגש דרך הכלב","text":"ללמוד לזהות את הרגש דרך הכלב"},{"id":"article-paragraph-090d99fa941e","heading":"ללמוד לזהות את הרגש דרך הכלב","text":"אחד השלבים החשובים בדרך לוויסות רגשי הוא היכולת להכיר את מה שאנחנו מרגישים."},{"id":"article-paragraph-add08324584e","heading":"ללמוד לזהות את הרגש דרך הכלב","text":"אצל ילדים, זה לא תמיד פשוט. לפעמים הם מרגישים כעס או פחד בעוצמה גדולה, אבל מתקשים לזהות את התחושה או להסביר מה קורה להם."},{"id":"article-paragraph-66125675f21c","heading":"ללמוד לזהות את הרגש דרך הכלב","text":"הכלבים מאפשרים לנו להתחיל את השיחה ממקום אחר."},{"id":"article-paragraph-9ef2ff95bb19","heading":"ללמוד לזהות את הרגש דרך הכלב","text":"אפשר להתבונן בכלב ולשאול: איך אנחנו יודעים שהוא מתרגש? איך הוא נראה כשהוא נינוח? מה הוא עושה כשהוא רוצה מרחב? איך אפשר לזהות שהוא מתוח?"},{"id":"article-paragraph-499a3ca2e9f0","heading":"ללמוד לזהות את הרגש דרך הכלב","text":"משם אפשר לעבור בהדרגה אל הילד."},{"id":"article-paragraph-ca4db6f9388b","heading":"ללמוד לזהות את הרגש דרך הכלב","text":"איך אתה מרגיש בגוף כשאתה כועס? מה אתה עושה כשאתה מתרגש? איך אפשר לזהות שאתה מתחיל להתעצבן, עוד לפני שהכעס נעשה חזק מאוד?"},{"id":"article-paragraph-85974b2ed2d2","heading":"ללמוד לזהות את הרגש דרך הכלב","text":"לפעמים הרבה יותר קל לילד לדבר קודם על הכלב, ורק אחר כך על עצמו."},{"id":"article-heading-6b910c7c11c1","heading":"משחק, המתנה וגמישות","text":"משחק, המתנה וגמישות"},{"id":"article-paragraph-d61ade97c203","heading":"משחק, המתנה וגמישות","text":"משחק הוא חלק משמעותי מהעבודה שלי עם ילדים, גם כשאין בו פעילות ישירה עם הכלב."},{"id":"article-paragraph-97b708114afe","heading":"משחק, המתנה וגמישות","text":"במשחק אנחנו פוגשים באופן טבעי מצבים של המתנה, הפסד, שינוי כללים, חוסר ודאות והתמודדות עם רצונות של אחרים."},{"id":"article-paragraph-29b2170bd194","heading":"משחק, המתנה וגמישות","text":"כשמשלבים גם כלב, מתווספת מערכת יחסים עם יצור חי שיש לו רצונות, צרכים וקצב משלו."},{"id":"article-paragraph-67cf9b6c1dcf","heading":"משחק, המתנה וגמישות","text":"הילד לא יכול לשלוט בכל מה שהכלב עושה. הוא צריך לפעמים לחכות, להתאים את עצמו, להתחשב ולמצוא דרך אחרת להשיג את המטרה שלו."},{"id":"article-paragraph-204f5c7608a4","heading":"משחק, המתנה וגמישות","text":"אלה הזדמנויות לעבוד על גמישות, סבלנות והתמודדות עם תסכול."},{"id":"article-paragraph-e11e4b170428","heading":"משחק, המתנה וגמישות","text":"אבל גם כאן, לא כל פעילות עם כלב היא בהכרח טיפולית. מה שהופך אותה לחלק מתהליך טיפולי הוא הקשר למטרות של הילד והאופן שבו אנחנו מתייחסים למה שמתרחש."},{"id":"article-heading-81155c2e0030","heading":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע","text":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע"},{"id":"article-paragraph-81de9ce20ffb","heading":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע","text":"אחד הדברים החשובים בעיניי בעבודה על ויסות רגשי הוא להבין שהיכולת הזאת מתפתחת בתוך קשר."},{"id":"article-paragraph-1313101be279","heading":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע","text":"כשילד מוצף רגשית, לא תמיד יש לו באותו רגע יכולת לעצור, לחשוב ולהשתמש בכלים שכבר למד."},{"id":"article-paragraph-693dd89410ca","heading":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע","text":"לפעמים הוא זקוק קודם כול למבוגר שיצליח להישאר רגוע יחסית מול הסערה שלו, להבין את הקושי ולעזור לו לחזור בהדרגה למצב שבו הוא מסוגל לחשוב ולפעול."},{"id":"article-paragraph-45e7e722c1cd","heading":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע","text":"התהליך הזה נקרא ויסות משותף (Co-regulation)."},{"id":"article-paragraph-b9a4cdd9c751","heading":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע","text":"בטיפול, הקשר עם המטפל הוא הבסיס שמאפשר את העבודה הזאת."},{"id":"article-paragraph-5748af3d8681","heading":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע","text":"הכלב יכול לעזור ביצירת קשר, לעורר תחושת ביטחון, לאפשר קרבה ולהפוך את המפגש לפחות מאיים עבור חלק מהילדים. לפעמים הנוכחות שלו גם מאפשרת לילד להביע דברים שהוא מתקשה להגיד בשיחה ישירה."},{"id":"article-paragraph-07a113fc92f7","heading":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע","text":"אבל המטרה היא לא שהילד יהיה תלוי בכלב כדי להירגע. אנחנו רוצים לעזור לו לפתח, בהדרגה, את היכולת להתמודד עם רגשותיו גם במצבים אחרים בחיים."},{"id":"article-heading-c03771f69452","heading":"ומה קורה כשהילד מתפרץ דווקא במהלך הטיפול?","text":"ומה קורה כשהילד מתפרץ דווקא במהלך הטיפול?"},{"id":"article-paragraph-a5b22a965ca9","heading":"ומה קורה כשהילד מתפרץ דווקא במהלך הטיפול?","text":"גם במהלך מפגש טיפולי יכולים להיות רגעים של כעס, התנגדות, בכי או תסכול."},{"id":"article-paragraph-6c6d9411a05f","heading":"ומה קורה כשהילד מתפרץ דווקא במהלך הטיפול?","text":"מבחינתי, אלה לא בהכרח רגעים שבהם הטיפול לא הצליח. לפעמים דווקא בהם מתאפשרת עבודה משמעותית."},{"id":"article-paragraph-f7a7d43b962e","heading":"ומה קורה כשהילד מתפרץ דווקא במהלך הטיפול?","text":"כשילד מתפרץ, לא תמיד הדבר הנכון הוא למהר להסביר לו איך היה צריך להתנהג או לדרוש ממנו להירגע מיד."},{"id":"article-paragraph-19d74914cdaf","heading":"ומה קורה כשהילד מתפרץ דווקא במהלך הטיפול?","text":"לפעמים חשוב קודם כול להבין מה הציף אותו, לעזור לו לשאת את הרגש ולתת לו תחושה שהוא לא נשאר לבד עם הקושי."},{"id":"article-paragraph-d081b5aa80ae","heading":"ומה קורה כשהילד מתפרץ דווקא במהלך הטיפול?","text":"רק כשהוא פנוי לכך, אפשר לחשוב יחד על מה שהיה ולנסות להבין מה יכול לעזור בפעם הבאה."},{"id":"article-paragraph-8d1e2f02eb1f","heading":"ומה קורה כשהילד מתפרץ דווקא במהלך הטיפול?","text":"כמובן, חלק מהאחריות שלי במפגשים היא גם לשמור על הכלבים. אם הילד מוצף מאוד, חשוב לדאוג למרחב בטוח עבור כולם ולא לצפות מהכלב לשאת התנהגות שעלולה להלחיץ אותו או לפגוע בו."},{"id":"article-heading-d32ad1172084","heading":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?","text":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?"},{"id":"article-paragraph-0e466af0a5e6","heading":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?","text":"העבודה על ויסות רגשי לא מסתיימת בחדר הטיפול, ולהורים יש תפקיד משמעותי מאוד בתהליך."},{"id":"article-paragraph-409d68c02370","heading":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?","text":"כשהילד כועס, אפשר לנסות לראות מעבר להתנהגות ולהבין מה הוא חווה. זה לא אומר לוותר על גבולות או לקבל פגיעה באחרים."},{"id":"article-paragraph-df769a220e54","heading":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?","text":"אפשר להגיד לילד שמותר לו לכעוס, אבל אסור לו להרביץ. אפשר להבין שהוא מאוכזב ובו בזמן לשמור על הגבול שהצבנו."},{"id":"article-paragraph-fd047a96296d","heading":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?","text":"כשהוא מוצף, כדאי להתאים את התגובה למצב שלו. לפעמים הוא זקוק לנוכחות ולסיוע ברגיעה יותר משהוא זקוק להסבר."},{"id":"article-paragraph-3943ec22c6d9","heading":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?","text":"אחרי שהסערה חולפת, אפשר לחזור יחד למה שקרה, לזהות את הקושי ולחשוב על דרכים נוספות להתמודד."},{"id":"article-paragraph-7b55fedd17cb","heading":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?","text":"חשוב גם לשים לב להצלחות הקטנות: ילד שהצליח לחכות עוד רגע, שלא ויתר אחרי כישלון, שביקש עזרה במקום להתפרץ או שהצליח לחזור למשחק לאחר שהתאכזב."},{"id":"article-paragraph-145ef11bf572","heading":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?","text":"ההצלחות האלה הן חלק מתהליך ההתפתחות, גם אם מבחוץ הן לא תמיד נראות גדולות."},{"id":"article-heading-ebbc5c9360e0","heading":"לסיכום – המטרה היא לא ילד שלא כועס","text":"לסיכום – המטרה היא לא ילד שלא כועס"},{"id":"article-paragraph-a8c7db91ba15","heading":"לסיכום – המטרה היא לא ילד שלא כועס","text":"כשאנחנו עובדים על ויסות רגשי אצל ילדים, אנחנו לא מנסים להעלים את הכעס, הפחד או התסכול."},{"id":"article-paragraph-b5cdee9c7096","heading":"לסיכום – המטרה היא לא ילד שלא כועס","text":"אנחנו רוצים לעזור לילדים להכיר את הרגשות שלהם, לשאת אותם, להיעזר באחרים כשצריך ולפתח בהדרגה את היכולת לבחור איך להגיב."},{"id":"article-paragraph-0f4100162119","heading":"לסיכום – המטרה היא לא ילד שלא כועס","text":"בטיפול רגשי בעזרת כלבים, הקשר עם הכלב, המשחק וההתנסויות המשותפות מאפשרים לפגוש את הקשיים האלה בדרך חווייתית."},{"id":"article-paragraph-2d4c1628aa15","heading":"לסיכום – המטרה היא לא ילד שלא כועס","text":"לא רק לדבר על תסכול, אלא להתמודד איתו. לא רק להסביר מהי סבלנות, אלא להתנסות בה. ולא רק ללמוד מה נכון לעשות כשכועסים, אלא לקבל הזדמנות לפתח את היכולת הזאת בתוך קשר טיפולי."}]},{"title":"מה כלבים עושים לנו? היתרונות של הקשר עם כלבים והשפעתם על הטיפול הרגשי","url":"https://derech-hakelev.com/articles/benefits-of-dogs-for-humans/","entries":[{"id":"article-title-ca554036d016","heading":"תחילת המאמר","text":"מה כלבים עושים לנו? היתרונות של הקשר עם כלבים והשפעתם על הטיפול הרגשי"},{"id":"article-paragraph-a2131b561b64","heading":"פתיחת המאמר","text":"מי שחי עם כלב מכיר את ההרגשה הזאת. חוזרים הביתה אחרי יום עמוס, הכלב מגיע לקבל את פנינו, ולפעמים עצם המפגש איתו כבר משנה משהו בהרגשה שלנו."},{"id":"article-paragraph-799d51422abb","heading":"פתיחת המאמר","text":"גם בעבודה הטיפולית שלי אני פוגש את ההשפעה הזאת. ילדים שמגיעים למפגש ומיד מחפשים את הכלב, אנשים שמרגישים בנוח לדבר כשהכלב נמצא לידם, ולפעמים גם רגעים שבהם נוכחות שקטה של כלב מאפשרת משהו שקשה להשיג בשיחה ישירה."},{"id":"article-paragraph-5bc63701ecca","heading":"פתיחת המאמר","text":"אבל מה באמת עומד מאחורי הקשר הזה? האם כלבים יכולים להפחית לחץ? האם הם משפיעים על מצב הרוח, על הבריאות הגופנית ועל הקשרים החברתיים שלנו? ומה הופך את הנוכחות שלהם למשמעותית כל כך דווקא בטיפול רגשי?"},{"id":"article-paragraph-9a288e954478","heading":"פתיחת המאמר","text":"בעשרים השנים האחרונות הצטברו מחקרים רבים שבחנו את הקשר בין בני אדם לכלבים. חלקם בדקו את ההשפעה של גידול כלב בבית, אחרים בחנו מפגשים קצרים עם כלבים, ומחקרים נוספים התמקדו בהתערבויות טיפוליות המשלבות כלבים."},{"id":"article-paragraph-b2708d6e3c7f","heading":"פתיחת המאמר","text":"התמונה שעולה מהם מעניינת: הקשר עם כלבים עשוי להשפיע עלינו בכמה מישורים במקביל - גופני, רגשי, חברתי וטיפולי."},{"id":"article-heading-18d9ddeb8240","heading":"כלבים יכולים לעזור לנו להירגע ולהפחית מתח","text":"כלבים יכולים לעזור לנו להירגע ולהפחית מתח"},{"id":"article-paragraph-7b47a1075bca","heading":"כלבים יכולים לעזור לנו להירגע ולהפחית מתח","text":"אחד התחומים הנחקרים ביותר הוא ההשפעה של מפגש עם כלבים על מתח ולחץ."},{"id":"article-paragraph-ec7819736a80","heading":"כלבים יכולים לעזור לנו להירגע ולהפחית מתח","text":"בשנת 2019 פורסם מחקר שבו השתתפו 249 סטודנטים. החוקרים חילקו אותם לקבוצות שונות: חלקם ליטפו כלבים וחתולים במשך עשר דקות, אחרים צפו באינטראקציה עם בעלי החיים, וקבוצות נוספות צפו בתמונות או המתינו."},{"id":"article-paragraph-2fdbf465725c","heading":"כלבים יכולים לעזור לנו להירגע ולהפחית מתח","text":"אצל המשתתפים שליטפו את בעלי החיים נמצאו לאחר הפעילות רמות נמוכות יותר של קורטיזול, הורמון המעורב בתגובת הגוף ללחץ, בהשוואה לקבוצות האחרות."},{"id":"article-paragraph-84baea222c94","heading":"כלבים יכולים לעזור לנו להירגע ולהפחית מתח","text":"גם סקירה מחקרית משנת 2025, שכללה 14 מחקרים בניתוח הכמותי, מצאה שהתערבויות בעזרת כלבים הפחיתו מתח וחרדה בקרב סטודנטים."},{"id":"article-paragraph-8d30649af4a3","heading":"כלבים יכולים לעזור לנו להירגע ולהפחית מתח","text":"הממצאים האלה מעניינים במיוחד משום שהם מצביעים על כך שההשפעה של מפגש עם בעל חיים אינה מתבטאת רק בתחושה סובייקטיבית של רוגע. בחלק מהמחקרים נמצאו גם שינויים במדדים גופניים הקשורים ללחץ."},{"id":"article-paragraph-fb39384fc004","heading":"כלבים יכולים לעזור לנו להירגע ולהפחית מתח","text":"מבחינה טיפולית, זה משמעותי. אדם שמגיע למפגש כשהוא מתוח, דרוך או חרד עשוי להתקשות להיפתח ולשתף. אם הנוכחות של הכלב מסייעת לו להרגיש מעט יותר בנוח, לפעמים כבר נוצר בסיס טוב יותר לעבודה."},{"id":"article-heading-8f780bd94738","heading":"הקשר עם כלבים משפיע גם על הגוף","text":"הקשר עם כלבים משפיע גם על הגוף"},{"id":"article-paragraph-1cc178a91fda","heading":"הקשר עם כלבים משפיע גם על הגוף","text":"ההשפעה של כלבים אינה מוגבלת לתחום הרגשי."},{"id":"article-paragraph-75379950c63b","heading":"הקשר עם כלבים משפיע גם על הגוף","text":"מחקרים שבדקו את בריאותם של בעלי כלבים מצאו קשר בין גידול כלב לבין פעילות גופנית מוגברת. הדבר לא מפתיע במיוחד: כלבים זקוקים לטיולים, לתנועה וליציאה מהבית, ולעיתים הם גורמים גם לבעליהם להיות פעילים יותר."},{"id":"article-paragraph-79cada9663af","heading":"הקשר עם כלבים משפיע גם על הגוף","text":"מטא־אנליזה משנת 2023, שהתבססה על 49 מחקרים, מצאה קשר חיובי בין גידול חיות מחמד לבין רמות הפעילות הגופנית של בעליהן."},{"id":"article-paragraph-0e3710ae90fc","heading":"הקשר עם כלבים משפיע גם על הגוף","text":"מחקרים אחרים בחנו גם את הקשר בין בעלות על כלבים לבריאות הלב וכלי הדם."},{"id":"article-paragraph-6c35651e383d","heading":"הקשר עם כלבים משפיע גם על הגוף","text":"סקירה ומטא-אנליזה שפורסמה בשנת 2019 בכתב עת של איגוד הלב האמריקאי כללה נתונים של כ-3.8 מיליון משתתפים. החוקרים מצאו שבעלות על כלב הייתה קשורה לסיכון נמוך יותר לתמותה במהלך תקופות המעקב, ובפרט לתמותה ממחלות לב וכלי דם."},{"id":"article-paragraph-0647bce0f24d","heading":"הקשר עם כלבים משפיע גם על הגוף","text":"חשוב להבחין כאן בין קשר סטטיסטי לבין השפעה ישירה: המחקר אינו מוכיח שעצם אימוץ הכלב הוא הסיבה לשיפור בבריאות. אבל הוא מחזק את העניין המחקרי בקשר שבין כלבים, אורח חיים פעיל ובריאות האדם."},{"id":"article-heading-5ff51dab5668","heading":"מה קורה במוח כשאנחנו יוצרים קשר עם כלב?","text":"מה קורה במוח כשאנחנו יוצרים קשר עם כלב?"},{"id":"article-paragraph-176c3729e479","heading":"מה קורה במוח כשאנחנו יוצרים קשר עם כלב?","text":"בשנת 2015 פורסם בכתב העת המדעי Science מחקר מעניין במיוחד על הקשר בין כלבים לבעליהם."},{"id":"article-paragraph-57089c71fc86","heading":"מה קורה במוח כשאנחנו יוצרים קשר עם כלב?","text":"החוקרים בחנו את התפקיד של אוקסיטוצין - הורמון המעורב, בין היתר, בקשרים חברתיים ובהתנהגויות של קרבה."},{"id":"article-paragraph-71ae5c84bfc8","heading":"מה קורה במוח כשאנחנו יוצרים קשר עם כלב?","text":"הם מצאו שכאשר כלבים ובעליהם הביטו זה בזה, משך המבט של הכלב היה קשור לעלייה ברמות האוקסיטוצין אצל הבעלים. החוקרים מצאו גם ראיות לתהליך הדדי של מבט וקשר בין הכלב לאדם."},{"id":"article-paragraph-3fc27f5db7c6","heading":"מה קורה במוח כשאנחנו יוצרים קשר עם כלב?","text":"הממצא הזה מציע הסבר ביולוגי לאחד הדברים שמרגישים באופן אינטואיטיבי בקשר עם כלבים: לפעמים לא צריך לעשות הרבה. מספיק מבט, קרבה או אינטראקציה פשוטה כדי לחוות תחושה משמעותית של קשר."},{"id":"article-paragraph-6efd6ccd311f","heading":"מה קורה במוח כשאנחנו יוצרים קשר עם כלב?","text":"כמובן, קשר רגשי הוא תהליך מורכב בהרבה מהפרשה של הורמון אחד, אבל המחקר הזה ממחיש עד כמה היחסים בין בני אדם לכלבים יכולים לערב מנגנונים ביולוגיים הקשורים לקרבה חברתית."},{"id":"article-heading-490318af1b0b","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים"},{"id":"article-paragraph-cdbbddafe4f3","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"כלבים לא משפיעים רק על הקשר שלנו איתם. לפעמים הם משפיעים גם על הקשרים שלנו עם אנשים אחרים."},{"id":"article-paragraph-04976dacaec7","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"מי שמטייל עם כלב מכיר את זה היטב: אנשים שלא היו פונים אלינו ברחוב עוצרים כדי לשאול עליו, ללטף אותו או לספר על הכלב שלהם."},{"id":"article-paragraph-c3b1ff70534a","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"לי אישית יש חברויות טובות שנוצרו בזכות הטיולים עם הכלבים."},{"id":"article-paragraph-e6f25d53c70a","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"מחקר משנת 2021 בחן את הקשר בין גידול כלבים, טיולים איתם והון חברתי - כלומר, קשרים, אמון ותחושת חיבור בין אנשים בקהילה."},{"id":"article-paragraph-f7cad2af0e6c","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"הכלב יכול להפוך למעין גורם מתווך שמקל על יצירת אינטראקציה חברתית."},{"id":"article-paragraph-7ecd543cc71c","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"בעבודה טיפולית יש לכך משמעות מיוחדת."},{"id":"article-paragraph-2e17b3f1473c","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"לא תמיד קל לילד או למבוגר להגיע למפגש עם אדם שאינו מכיר ולהתחיל לדבר על עצמו. הכלב יכול ליצור נושא משותף, לאפשר פעילות משותפת ולהפחית את הצורך בשיחה ישירה כבר מהרגע הראשון."},{"id":"article-paragraph-4b5bbf3d16d7","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"במקום להתחיל בשאלה \"איך אתה מרגיש?\", אפשר להתחיל מהיכרות עם הכלב, ממשחק או מפעילות פשוטה."},{"id":"article-paragraph-fe81a7130de1","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"לעיתים דווקא הדרך העקיפה הזאת מאפשרת לקשר הטיפולי להתפתח בצורה טבעית יותר."},{"id":"article-heading-92938ef56a59","heading":"כלבים, מצב רוח ותחושת בדידות","text":"כלבים, מצב רוח ותחושת בדידות"},{"id":"article-paragraph-10eb35999906","heading":"כלבים, מצב רוח ותחושת בדידות","text":"עבור אנשים רבים, כלב הוא חלק משמעותי מחיי היום-יום: מישהו שמחכה בבית, זקוק לנו, מלווה אותנו בשגרה ונמצא איתנו גם בתקופות קשות."},{"id":"article-paragraph-b0d602b5987d","heading":"כלבים, מצב רוח ותחושת בדידות","text":"בתחום המחקרי, אחת השאלות היא האם מפגשים עם בעלי חיים יכולים לתרום לרווחה הנפשית, במיוחד אצל אנשים מבוגרים או אנשים המתמודדים עם קשיים רגשיים."},{"id":"article-paragraph-a49e6eddc3f3","heading":"כלבים, מצב רוח ותחושת בדידות","text":"מטא-אנליזה שפורסמה בשנת 2026 ובחנה התערבויות בעזרת בעלי חיים בקרב מבוגרים בגיל השלישי מצאה שיפור בתסמיני דיכאון ובתפקוד הקוגניטיבי."},{"id":"article-paragraph-a7f34bb8bcd1","heading":"כלבים, מצב רוח ותחושת בדידות","text":"מבחינתי, אחד הדברים המעניינים בקשר עם כלב הוא העובדה שהוא מזמן גם קשר וגם עשייה. אנחנו לא רק מקבלים ממנו תשומת לב, אלא גם אחראים לו, דואגים לצרכיו ופועלים יחד איתו."},{"id":"article-paragraph-22ff1abd4669","heading":"כלבים, מצב רוח ותחושת בדידות","text":"לכן, כאשר משלבים כלבים בתהליך טיפולי, אפשר לעבוד לא רק דרך מגע וקרבה, אלא גם דרך פעילות, אחריות, יוזמה והתנסות."},{"id":"article-heading-4a310cfc2d1b","heading":"איך כלבים יכולים לעזור לילדים?","text":"איך כלבים יכולים לעזור לילדים?"},{"id":"article-paragraph-3c5e11193bda","heading":"איך כלבים יכולים לעזור לילדים?","text":"ילדים רבים נמשכים באופן טבעי לכלבים. הם רוצים ללטף, לשחק, להוביל אותם, ללמד אותם תרגילים ולבלות בקרבתם."},{"id":"article-paragraph-f2aab2065ef7","heading":"איך כלבים יכולים לעזור לילדים?","text":"המשיכה הזאת יכולה ליצור הזדמנויות משמעותיות גם בתחומים רגשיים וחברתיים."},{"id":"article-paragraph-b3d79d83b0f6","heading":"איך כלבים יכולים לעזור לילדים?","text":"בשנת 2025 פורסמה סקירה שיטתית של 30 מחקרים שבחנו התערבויות בעזרת בעלי חיים בקרב ילדים בגיל בית הספר. בסקירה נמצאו ממצאים חיוביים בתחומי התפקוד החברתי-רגשי, ההתנהגות והלמידה."},{"id":"article-paragraph-835ae4e72711","heading":"איך כלבים יכולים לעזור לילדים?","text":"בעבודה עם כלבים, אפשר להפוך את התחומים האלה לחלק מהתנסות ממשית."},{"id":"article-paragraph-79ae749a738b","heading":"איך כלבים יכולים לעזור לילדים?","text":"ילד שמנסה ללמד כלב תרגיל עשוי לפגוש תסכול כשהכלב לא מצליח. ילד שמכין לכלב מסלול מכשולים צריך לפעמים להתאים את התוכנית שלו למציאות. וילד שמתקשה להמתין יכול לתרגל סבלנות בתוך פעילות שיש לו מוטיבציה להשתתף בה."},{"id":"article-paragraph-70c81cd24d0b","heading":"איך כלבים יכולים לעזור לילדים?","text":"המשמעות היא שלא חייבים לדבר באופן ישיר על כל קושי כדי לעבוד עליו."},{"id":"article-paragraph-fbd1dba7da8e","heading":"איך כלבים יכולים לעזור לילדים?","text":"לפעמים הסיטואציה הטיפולית עצמה מאפשרת לילד לפגוש את הקושי, ובעזרת המטפל ללמוד להתמודד איתו בדרך אחרת."},{"id":"article-heading-2030e7a2d1bf","heading":"כלבים וילדים על הרצף האוטיסטי","text":"כלבים וילדים על הרצף האוטיסטי"},{"id":"article-paragraph-e3a8d3329800","heading":"כלבים וילדים על הרצף האוטיסטי","text":"אחד התחומים שבהם נחקרה העבודה בעזרת כלבים הוא התערבויות עם ילדים ובני נוער על הרצף האוטיסטי."},{"id":"article-paragraph-d44793c50cc2","heading":"כלבים וילדים על הרצף האוטיסטי","text":"סקירה שיטתית משנת 2024, שהתמקדה בטיפול בעזרת כלבים, כללה 19 מאמרים. בחלק גדול מהמחקרים דווח על שיפור בתקשורת ובאינטראקציה חברתית."},{"id":"article-paragraph-ef226029de36","heading":"כלבים וילדים על הרצף האוטיסטי","text":"במחקרים מסוימים נמצאו גם שינויים חיוביים במדדים רגשיים והתנהגותיים."},{"id":"article-paragraph-c2ba60ae24d4","heading":"כלבים וילדים על הרצף האוטיסטי","text":"אחת האפשרויות שמציעים החוקרים היא שהכלב יכול לשמש גורם שמושך את תשומת הלב ומעודד אינטראקציה."},{"id":"article-paragraph-4a7a7d1275eb","heading":"כלבים וילדים על הרצף האוטיסטי","text":"אפשר להבין זאת גם דרך ההתנסות: הפעילות עם הכלב יוצרת סיבה משותפת לתקשר, לשתף פעולה, להתבונן, להגיב ולפעול יחד."},{"id":"article-paragraph-bb07252205be","heading":"כלבים וילדים על הרצף האוטיסטי","text":"גם כאן חשוב לראות את הילד ואת הצרכים הייחודיים שלו. המטרה אינה ללמד כל ילד להתנהג בדרך מסוימת, אלא להבין אילו יכולות הוא רוצה לפתח וכיצד הקשר והפעילות עם הכלב יכולים לסייע לו."},{"id":"article-heading-57612f31b6fb","heading":"הקלה על כאב ומתח במצבים רפואיים","text":"הקלה על כאב ומתח במצבים רפואיים"},{"id":"article-paragraph-3f90a2a3b3bc","heading":"הקלה על כאב ומתח במצבים רפואיים","text":"תחום נוסף שבו נחקרו התערבויות בעזרת בעלי חיים הוא בתי חולים ומסגרות רפואיות."},{"id":"article-paragraph-01f8e7c8d707","heading":"הקלה על כאב ומתח במצבים רפואיים","text":"עבור ילדים, אשפוז עשוי להיות חוויה מאיימת: סביבה לא מוכרת, בדיקות, כאב, פרידה מהשגרה ולעיתים גם פחד מהטיפול הרפואי."},{"id":"article-paragraph-093f17b092a2","heading":"הקלה על כאב ומתח במצבים רפואיים","text":"סקירה ומטא-אנליזה משנת 2021 בחנה שמונה מחקרים שכללו יחד 348 ילדים ובני נוער מאושפזים."},{"id":"article-paragraph-66aeb39fad2a","heading":"הקלה על כאב ומתח במצבים רפואיים","text":"החוקרים מצאו שבקבוצות שקיבלו התערבות בעזרת בעלי חיים נמדדו רמות כאב נמוכות יותר בהשוואה לקבוצות הביקורת."},{"id":"article-paragraph-f28b6ff4efe3","heading":"הקלה על כאב ומתח במצבים רפואיים","text":"הממצא הזה מעניין משום שהוא מדגים את האפשרות של מפגש עם בעל חיים לשמש מרכיב תומך גם במצבים שבהם הקושי אינו רק רגשי, אלא קשור לחוויה גופנית ממשית."},{"id":"article-heading-c33a9de62408","heading":"כלבים בהתמודדות עם פוסט טראומה","text":"כלבים בהתמודדות עם פוסט טראומה"},{"id":"article-paragraph-c219fdf84b59","heading":"כלבים בהתמודדות עם פוסט טראומה","text":"בעשור האחרון גבר גם העניין המחקרי בכלבי שירות עבור אנשים המתמודדים עם הפרעת דחק פוסט טראומטית (PTSD)."},{"id":"article-paragraph-9669a6502843","heading":"כלבים בהתמודדות עם פוסט טראומה","text":"מחקר שפורסם בשנת 2024 בכתב העת JAMA Network Open בחן 156 אנשי צבא ויוצאי צבא אמריקאים המתמודדים עם PTSD."},{"id":"article-paragraph-ae7e2ca6bf81","heading":"כלבים בהתמודדות עם פוסט טראומה","text":"החוקרים השוו בין אנשים שקיבלו כלב שירות פסיכיאטרי לצד הטיפול הרגיל שלהם, לבין אנשים שהמשיכו לקבל טיפול רגיל ללא כלב שירות בתקופת המחקר."},{"id":"article-paragraph-7324120f1abe","heading":"כלבים בהתמודדות עם פוסט טראומה","text":"לאחר שלושה חודשים, הקבוצה שקיבלה כלבי שירות הציגה חומרה נמוכה יותר של תסמיני PTSD ותפקוד פסיכו-חברתי טוב יותר."},{"id":"article-paragraph-05cf53ebd5dd","heading":"כלבים בהתמודדות עם פוסט טראומה","text":"חשוב להבחין בין כלב שירות שמלווה אדם בחיי היום-יום לבין כלב המשתלב במפגש טיפולי. אלה התערבויות שונות, עם מטרות ותפקידים שונים."},{"id":"article-paragraph-fe0f54f2f0d7","heading":"כלבים בהתמודדות עם פוסט טראומה","text":"עם זאת, המחקר ממחיש את הפוטנציאל של קשר מתמשך עם כלב כחלק ממערך התמיכה באנשים המתמודדים עם מצוקה נפשית."},{"id":"article-heading-e9f3a8dea3d6","heading":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?","text":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?"},{"id":"article-paragraph-4a3418eea8b2","heading":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?","text":"עד עכשיו עסקנו בהשפעות האפשריות של כלבים על הגוף, על הרגש ועל הקשרים החברתיים."},{"id":"article-paragraph-cf567d1509b9","heading":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?","text":"אבל יש שאלה נוספת שמעניינת אותי במיוחד כמטפל: מה הופך את כל היתרונות האלה למשמעותיים בתוך חדר הטיפול?"},{"id":"article-paragraph-39f66318c486","heading":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?","text":"בעיניי, התשובה נמצאת בשילוב בין הקשר שנוצר עם הכלב לבין האפשרויות שהקשר הזה פותח."},{"id":"article-paragraph-46be39099d00","heading":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?","text":"ראשית, הכלב יכול לעזור ביצירת הקשר הראשוני. עבור ילדים ומבוגרים שמתקשים לתת אמון או להרגיש בנוח בטיפול, הכלב יכול לשמש גשר לקשר עם המטפל."},{"id":"article-paragraph-e6d3978ca22d","heading":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?","text":"שנית, הכלב מאפשר ביטוי רגשי גם בלי שיחה ישירה. לפעמים קל יותר לדבר על מה שהכלב מרגיש, על הקושי שלו או על מה שהוא צריך, ורק בהמשך לחבר את הדברים לחוויה האישית שלנו."},{"id":"article-paragraph-33266954fff3","heading":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?","text":"שלישית, הכלב מזמן התנסויות אמיתיות. הוא לא תמיד משתף פעולה, יש לו רצונות וצרכים משלו, והוא מגיב למה שמתרחש סביבו. לכן אפשר לפגוש במהלך הפעילות רגשות כמו תסכול, התרגשות, פחד, הצלחה וגאווה."},{"id":"article-paragraph-9dbe0effb833","heading":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?","text":"ורביעית, הכלב מאפשר לשלב משחק, תנועה וקשר בתוך אותו מפגש. לא כל אדם מתחבר לטיפול שמתבסס בעיקר על שיחה. עבור חלק מהמטופלים, דווקא העשייה המשותפת היא שמאפשרת בהמשך גם שיח רגשי עמוק יותר."},{"id":"article-heading-a3b439588bc7","heading":"לסיכום - הרבה מעבר לחברו הטוב של האדם","text":"לסיכום - הרבה מעבר לחברו הטוב של האדם"},{"id":"article-paragraph-25af5ca1a73d","heading":"לסיכום - הרבה מעבר לחברו הטוב של האדם","text":"המחקרים מהשנים האחרונות מלמדים שהקשר בין בני אדם לכלבים עשוי להיות משמעותי הרבה מעבר להנאה ולחברות."},{"id":"article-paragraph-be997516c412","heading":"לסיכום - הרבה מעבר לחברו הטוב של האדם","text":"הוא קשור להפחתת מתח, לתהליכים ביולוגיים של קרבה וקשר, לפעילות גופנית, להזדמנויות חברתיות וליתרונות אפשריים במגוון התערבויות טיפוליות."},{"id":"article-paragraph-50616ad5df63","heading":"לסיכום - הרבה מעבר לחברו הטוב של האדם","text":"בעיניי, הייחוד של הכלב בטיפול אינו נמצא רק ביכולת שלו לעורר רוגע או שמחה."},{"id":"article-paragraph-32adb86dbd0a","heading":"לסיכום - הרבה מעבר לחברו הטוב של האדם","text":"הוא נמצא בכך שהכלב הוא יצור חי שאפשר ליצור איתו קשר, לפעול לצידו, להתמודד איתו עם אתגרים ולחוות דרכו מצבים רגשיים אמיתיים."},{"id":"article-paragraph-b301c962620d","heading":"לסיכום - הרבה מעבר לחברו הטוב של האדם","text":"כאשר כל אלה משתלבים בתוך קשר טיפולי מקצועי ומותאם, הם יכולים להפוך לחלק משמעותי מתהליך של שינוי והתפתחות."},{"id":"article-reference-c5a93b9de9bc","heading":"מקורות","text":"Pendry & Vandagriff (2019) מחקר אקראי על השפעת מפגש עם בעלי חיים על רמות קורטיזול בקרב סטודנטים."},{"id":"article-reference-bdd0b8524c34","heading":"מקורות","text":"Sim et al. (2025) סקירה שיטתית ומטא־אנליזה על הפחתת מתח וחרדה באמצעות התערבויות עם כלבים בקרב סטודנטים."},{"id":"article-reference-86745eaf7205","heading":"מקורות","text":"Nagasawa et al. (2015) מחקר ב־Science על מבט הדדי ואוקסיטוצין בקשר בין כלבים לבני אדם."},{"id":"article-reference-959ba36a6eed","heading":"מקורות","text":"Martins et al. (2023) מטא־אנליזה על גידול חיות מחמד, פעילות גופנית ובריאות נפשית."},{"id":"article-reference-34946b9d4fc8","heading":"מקורות","text":"Kramer et al. (2019) מטא־אנליזה על בעלות על כלבים והקשר לתמותה ולבריאות הלב."},{"id":"article-reference-2d2530b65140","heading":"מקורות","text":"Koohsari et al. (2021) מחקר על בעלות על כלבים, טיולים והון חברתי."},{"id":"article-reference-2ac5b7eec80f","heading":"מקורות","text":"Moe et al. (2025) סקירה שיטתית על התערבויות בעזרת בעלי חיים בילדים בגיל בית הספר."},{"id":"article-reference-3564f9a0ce08","heading":"מקורות","text":"Galvany-López et al. (2024) סקירה שיטתית על טיפול בעזרת כלבים בקרב ילדים ובני נוער על הרצף האוטיסטי."},{"id":"article-reference-1b80674ae9ce","heading":"מקורות","text":"Feng et al. (2021) סקירה ומטא־אנליזה על התערבויות בעזרת בעלי חיים בקרב ילדים מאושפזים."},{"id":"article-reference-31ccc27158aa","heading":"מקורות","text":"Leighton et al. (2024) מחקר מבוקר על כלבי שירות פסיכיאטריים בקרב אנשי צבא עם PTSD."},{"id":"article-reference-194017e05ac2","heading":"מקורות","text":"Shoesmith et al. (2025) סקירה שיטתית על התערבויות בעזרת כלבים בקרב ילדים ומבוגרים עם קשיים נפשיים או נוירו־התפתחותיים."},{"id":"article-reference-3a19d75406a4","heading":"מקורות","text":"Lv et al. (2026) סקירה שיטתית ומטא־אנליזה על התערבויות בעזרת בעלי חיים חיים ורובוטיים, תסמיני דיכאון ותפקוד קוגניטיבי בגיל השלישי."}]},{"title":"התמודדות עם תסכול אצל ילדים - למה זה כל כך קשה ואיך אפשר לעזור?","url":"https://derech-hakelev.com/pages/articles/frustration-children-dog-therapy/","entries":[{"id":"article-title-1574d71159f5","heading":"תחילת המאמר","text":"התמודדות עם תסכול אצל ילדים - למה זה כל כך קשה ואיך אפשר לעזור?"},{"id":"article-paragraph-c72c30a2d189","heading":"פתיחת המאמר","text":"הילד מתעצבן כשהוא מפסיד במשחק? מוותר על משימה ברגע שהוא לא מצליח? מתפרץ כשאומרים לו לא, או כשהדברים לא מתרחשים בדיוק כפי שרצה?"},{"id":"article-paragraph-983d7dd57c01","heading":"פתיחת המאמר","text":"תסכול הוא אחד הרגשות שאנחנו פוגשים כמעט בכל יום, ובכל גיל. אנחנו מתכננים משהו שלא מצליח, רוצים דבר שאנחנו לא יכולים לקבל, מנסים להשיג מטרה ונתקלים בקושי."},{"id":"article-paragraph-fc8297610bfd","heading":"פתיחת המאמר","text":"אצל ילדים, התסכול יכול להתבטא בצורה עוצמתית במיוחד. לפעמים מדובר בבכי, בכעס או בהתפרצות, ולפעמים דווקא בהסתגרות, בוויתור מהיר או בהימנעות מניסיון נוסף."},{"id":"article-paragraph-8e3362313772","heading":"פתיחת המאמר","text":"אבל חשוב לי להתחיל דווקא מהנקודה הזאת: תסכול הוא לא דבר רע. הוא חלק טבעי ובלתי נפרד מהחיים, ויש לו גם תפקיד חשוב בהתפתחות שלנו."},{"id":"article-paragraph-5fdcf8e25453","heading":"פתיחת המאמר","text":"השאלה היא לא איך אנחנו מונעים מילדים להרגיש תסכול, אלא איך אנחנו עוזרים להם לפתח את היכולת להתמודד איתו."},{"id":"article-heading-f0e45ce32538","heading":"מה זה בכלל תסכול?","text":"מה זה בכלל תסכול?"},{"id":"article-paragraph-d3cb22e64ab4","heading":"מה זה בכלל תסכול?","text":"תסכול הוא התחושה שמתעוררת כשמשהו שאנחנו רוצים או מנסים להשיג לא מתאפשר לנו."},{"id":"article-paragraph-053793307e42","heading":"מה זה בכלל תסכול?","text":"למשל, ילד שרוצה להמשיך לשחק אבל צריך ללכת לישון, ילד שמנסה לבנות מגדל והמגדל נופל שוב ושוב, או ילד שרוצה להצטרף למשחק והחברים לא משתפים אותו."},{"id":"article-paragraph-605b8067bb81","heading":"מה זה בכלל תסכול?","text":"בכל המצבים האלה יש פער בין מה שהילד רוצה שיקרה לבין מה שקורה בפועל."},{"id":"article-paragraph-cbe9b4dd2f7b","heading":"מה זה בכלל תסכול?","text":"תסכול יכול לעורר כעס, אכזבה, עצב, חוסר אונים ולעיתים גם רצון לוותר או להתרחק."},{"id":"article-paragraph-54aaa7a8e025","heading":"מה זה בכלל תסכול?","text":"יש משהו חשוב בתסכול: פעמים רבות הוא זה שמניע אותנו לפעול. כשמשהו לא מצליח, התסכול יכול לגרום לנו לנסות שוב, להשקיע יותר מאמץ, לחפש פתרון אחר או לבקש עזרה."},{"id":"article-paragraph-b0d05c6f8627","heading":"מה זה בכלל תסכול?","text":"אבל כשהתסכול נעשה גדול מדי, או כשהילד מתקשה לשאת אותו, הוא יכול גם להוביל לתגובות שפוגעות בו ובסביבה שלו."},{"id":"article-heading-d122ff1b1963","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?"},{"id":"article-paragraph-413eab4705ca","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"לא כל הילדים מבטאים תסכול באותה הדרך."},{"id":"article-paragraph-f824670cd825","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"יש ילדים שכשהם לא מצליחים משהו, הם מתעצבנים מאוד, צועקים, בוכים או זורקים חפצים. אחרים יאמרו מיד \"אני לא יודע\", \"אני לא מצליח\" או \"זה משחק מטומטם\", ויוותרו לפני שבאמת ניסו."},{"id":"article-paragraph-8f3630eb266e","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"יש גם ילדים שהתסכול שלהם פחות נראה לעין. הם עשויים להימנע ממשחקים שבהם אפשר להפסיד, לא לרצות לנסות דברים חדשים או להתרחק ממצבים שבהם הם לא בטוחים שיצליחו."},{"id":"article-paragraph-62ddf0c244ab","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"לעיתים נראה קושי סביב מצבים כמו:"},{"id":"article-item-c0af932a7011","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"הפסד במשחק או כישלון במשימה."},{"id":"article-item-bbde1eb90ae5","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"קבלת תשובה שלילית מההורים."},{"id":"article-item-d8e85679a00f","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"המתנה או דחיית סיפוקים."},{"id":"article-item-c1160d6fb902","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"שינוי בתוכניות או חוסר שליטה במצב."},{"id":"article-item-55e006050dd2","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"קושי חברתי, דחייה או ריב עם חבר."},{"id":"article-item-233d9ee37ba4","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"תחושה שמישהו אחר לא מבין אותם או לא מקשיב להם."},{"id":"article-paragraph-063d5ae621fb","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"מה שמשותף למצבים האלה הוא שהילד פוגש מציאות שלא מתאימה למה שהוא רצה או ציפה."},{"id":"article-heading-46400be5bce6","heading":"מתי תסכול הוא דבר טבעי, ומתי הוא הופך לבעיה?","text":"מתי תסכול הוא דבר טבעי, ומתי הוא הופך לבעיה?"},{"id":"article-paragraph-87fb17bd2754","heading":"מתי תסכול הוא דבר טבעי, ומתי הוא הופך לבעיה?","text":"לפעמים הורים מודאגים מכך שהילד שלהם מתוסכל בקלות. אבל עצם העובדה שילד מתוסכל, בוכה או אפילו כועס מאוד, לא אומרת בהכרח שיש בעיה."},{"id":"article-paragraph-768a48568d95","heading":"מתי תסכול הוא דבר טבעי, ומתי הוא הופך לבעיה?","text":"ילדים עדיין מפתחים את היכולת להתמודד עם רגשות חזקים. ילד בן שלוש שמתקשה לקבל תשובה שלילית נמצא בשלב התפתחותי אחר לגמרי מילד בן עשר שמגיב באותה הדרך."},{"id":"article-paragraph-2217b67cf673","heading":"מתי תסכול הוא דבר טבעי, ומתי הוא הופך לבעיה?","text":"לכן, השאלה היא לא רק האם הילד מתוסכל, אלא איך הוא מתמודד עם התסכול, באיזו תדירות זה קורה, כמה זמן לוקח לו להתאושש ועד כמה הדבר משפיע על חייו."},{"id":"article-paragraph-5dbdbdd41c20","heading":"מתי תסכול הוא דבר טבעי, ומתי הוא הופך לבעיה?","text":"כשילד מתפרץ בעוצמה כמעט בכל פעם שמשהו לא מצליח, פוגע בעצמו או באחרים, נמנע באופן קבוע מהתמודדויות, או כשהקושי פוגע בלימודים, בחברויות ובמשפחה, כדאי להתייחס אליו ולבחון האם הוא זקוק לעזרה."},{"id":"article-paragraph-42c3e36eb6fb","heading":"מתי תסכול הוא דבר טבעי, ומתי הוא הופך לבעיה?","text":"לעומת זאת, ילד שמתאכזב, בוכה קצת, כועס ולאחר מכן מצליח להמשיך הלאה, אינו בהכרח ילד שמתקשה בוויסות. לפעמים הוא פשוט ילד שחווה תסכול ומבטא אותו."},{"id":"article-paragraph-e01435be5d63","heading":"מתי תסכול הוא דבר טבעי, ומתי הוא הופך לבעיה?","text":"המטרה שלנו לא צריכה להיות לגדל ילדים שלא מתוסכלים, אלא ילדים שמסוגלים לפגוש תסכול ולהתמודד איתו."},{"id":"article-heading-5388eda12b26","heading":"למה יש ילדים שמתקשים יותר להתמודד עם תסכול?","text":"למה יש ילדים שמתקשים יותר להתמודד עם תסכול?"},{"id":"article-paragraph-f09b9cea2a83","heading":"למה יש ילדים שמתקשים יותר להתמודד עם תסכול?","text":"היכולת להתמודד עם תסכול מושפעת ממספר גורמים."},{"id":"article-paragraph-8fc8ffb10834","heading":"למה יש ילדים שמתקשים יותר להתמודד עם תסכול?","text":"יש ילדים שמלכתחילה חווים רגשות בעוצמה גבוהה יותר, או מתקשים יותר לעכב תגובה. אחרים מתקשים בגמישות מחשבתית, בהמתנה, בהתמודדות עם חוסר ודאות או בקבלת שינויים."},{"id":"article-paragraph-b71662e349b4","heading":"למה יש ילדים שמתקשים יותר להתמודד עם תסכול?","text":"לפעמים גם הניסיון שהילד צבר משפיע. ילד שחווה הרבה כישלונות, ביקורת או תחושה שהוא לא מספיק טוב, עשוי להגיע להתנסות חדשה כשהוא כבר מצפה שלא יצליח."},{"id":"article-paragraph-a7bba17f3e28","heading":"למה יש ילדים שמתקשים יותר להתמודד עם תסכול?","text":"במצבים כאלה, אפילו קושי קטן עלול לעורר תגובה חזקה."},{"id":"article-paragraph-643beb4051f5","heading":"למה יש ילדים שמתקשים יותר להתמודד עם תסכול?","text":"גם לאופן שבו המבוגרים מגיבים לתסכול יש משמעות. אם אנחנו ממהרים תמיד לפתור לילד כל קושי, הוא עלול לקבל פחות הזדמנויות להתנסות בהתמודדות. מצד שני, אם בכל פעם שהוא מתוסכל הוא פוגש כעס, ביקורת או חוסר סבלנות, התסכול המקורי עלול להפוך לחוויה קשה עוד יותר."},{"id":"article-paragraph-4c7ef900744f","heading":"למה יש ילדים שמתקשים יותר להתמודד עם תסכול?","text":"לכן, לא מספיק ללמד ילד מה לעשות כשהוא מתוסכל. חשוב גם להבין מה עומד מאחורי הקושי שלו, ומה הוא צריך מאיתנו באותו רגע."},{"id":"article-heading-5b5eaed03208","heading":"מה הקשר בין תסכול להיקשרות?","text":"מה הקשר בין תסכול להיקשרות?"},{"id":"article-paragraph-24481ba123d0","heading":"מה הקשר בין תסכול להיקשרות?","text":"אחד הדברים המרכזיים בגישה ההתפתחותית-היקשרותית הוא ההבנה שהתפתחות רגשית מתרחשת בתוך קשר."},{"id":"article-paragraph-d4054fc070be","heading":"מה הקשר בין תסכול להיקשרות?","text":"כשילד פוגש משהו שהוא לא מצליח לשנות, הוא זקוק לא פעם למבוגר שיכול להיות איתו בתוך האכזבה, הכעס או חוסר האונים."},{"id":"article-paragraph-0c5a4329510d","heading":"מה הקשר בין תסכול להיקשרות?","text":"לפי הגישה של גורדון ניופלד, לתסכול יש כמה כיוונים אפשריים."},{"id":"article-paragraph-dc58b79caf20","heading":"מה הקשר בין תסכול להיקשרות?","text":"לפעמים הוא מניע אותנו לשנות את המצב: לנסות שוב, להתאמץ או למצוא דרך אחרת."},{"id":"article-paragraph-873da75eb103","heading":"מה הקשר בין תסכול להיקשרות?","text":"אבל לפעמים אנחנו פוגשים משהו שאי אפשר לשנות. במקרה כזה, ההתפתחות אינה נמצאת בעוד ניסיון להילחם במציאות, אלא ביכולת להרגיש את האכזבה, לקבל את מה שלא ניתן לשנות ולהסתגל."},{"id":"article-paragraph-66df64f64f33","heading":"מה הקשר בין תסכול להיקשרות?","text":"אפשר לראות זאת אצל ילד שמאוד רוצה לקבל משהו, אבל הדבר פשוט אינו אפשרי. לפעמים הוא ינסה להתווכח, לכעוס או לשנות את דעתו של ההורה. בהמשך, אם הוא יוכל לפגוש את האכזבה ולהרגיש בטוח בקשר, תיתכן תנועה מהכעס אל העצב והקבלה."},{"id":"article-paragraph-a9cae44b8344","heading":"מה הקשר בין תסכול להיקשרות?","text":"מבחינתי, זה אחד הדברים החשובים בעבודה עם ילדים: לא כל קושי צריך לפתור, ולא כל תסכול צריך להעלים."},{"id":"article-paragraph-0fa7f87cdfe6","heading":"מה הקשר בין תסכול להיקשרות?","text":"לפעמים צריך לעזור לילד לגלות שהוא מסוגל להתמודד גם עם דברים שלא מתרחשים כפי שהיה רוצה."},{"id":"article-paragraph-797e8c535822","heading":"מה הקשר בין תסכול להיקשרות?","text":"הקשר הבטוח עם המבוגר הוא מה שמאפשר לילד לפגוש את הרגשות האלה מבלי להרגיש שהוא נשאר איתם לבד."},{"id":"article-paragraph-f090375d0b46","heading":"מה הקשר בין תסכול להיקשרות?","text":"לקריאה נוספת: הגישה ההתפתחותית-היקשרותית בטיפול בעזרת כלבים."},{"id":"article-heading-7fa4ea504bb7","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?"},{"id":"article-paragraph-5c609e1d4e08","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אחד הדברים שאני אוהב בעבודה עם כלבים הוא האפשרות ליצור התנסויות שבהן הילד פוגש רגשות אמיתיים, ולא רק מדבר עליהם באופן תיאורטי."},{"id":"article-paragraph-b4250e798946","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אבל יש נקודה שחשוב לי להדגיש: אני לא מתחיל לעבוד באופן מכוון על תסכול במפגשים הראשונים."},{"id":"article-paragraph-9bdf6df812d4","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"לפני שאנחנו מציבים לילד אתגרים, חשוב קודם כול לבסס את הקשר הטיפולי."},{"id":"article-paragraph-8c9b927b7090","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אני רוצה שהילד ירגיש בנוח איתי, שיכיר אותי, שירגיש שהוא יכול לסמוך עליי ושגם אם משהו לא יצליח, הוא עדיין נמצא במקום בטוח."},{"id":"article-paragraph-e3275a48ff45","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"רק כשהקשר מספיק יציב, וכשאני מעריך שאפשר לפגוש תסכול מבלי שהדבר יערער את תחושת הביטחון של הילד בקשר, אני מתחיל לשלב התנסויות מכוונות."},{"id":"article-paragraph-9967651322f2","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"וגם אז, המטרה היא לא להציף את הילד, אלא ליצור קושי שאפשר להתמודד איתו, לדבר עליו וללמוד ממנו."},{"id":"article-heading-09c2dd1473ac","heading":"מה קורה כשהכלב פשוט לא מצליח?","text":"מה קורה כשהכלב פשוט לא מצליח?"},{"id":"article-paragraph-1862c17a0a8b","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אחת הפעילויות שאני משתמש בהן היא עבודה עם הכלבים על ביצוע תרגילים."},{"id":"article-paragraph-d983c3f24ea1","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אני יכול לבקש מהילד ללמד כלב לבצע גלגול. בהתחלה נעבוד עם כלב שמכיר את התרגיל. זה לא בהכרח יהיה קל, אבל בסופו של דבר הילד בדרך כלל מצליח."},{"id":"article-paragraph-a7eebcf451d5","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"לאחר מכן אני יכול לבקש ממנו לנסות את אותו התרגיל עם ליאו, כלב שלא יודע לבצע גלגול."},{"id":"article-paragraph-8c97823cca31","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אני יודע מראש שהתרגיל לא צפוי להצליח, אבל הילד עדיין לא יודע את זה."},{"id":"article-paragraph-ab06c1186760","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"במהלך הפעילות אני מתבונן במה שמתרחש."},{"id":"article-paragraph-57e466d59947","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"כמה זמן הוא מנסה? האם הוא מתעצבן? האם הוא מוותר מהר? האם הוא מנסה לשנות את הדרך שבה הוא מסביר לכלב? האם הוא מבקש עזרה?"},{"id":"article-paragraph-fe42a8ec7c09","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אחרי ההתנסות, כשהילד פנוי לשיחה, אני יכול לשאול אותו מה הוא הרגיש."},{"id":"article-paragraph-1b095d026617","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"ואז אנחנו מדברים גם על ליאו."},{"id":"article-paragraph-eb5233b66f79","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"איך לדעתך הוא הרגיש? האם יכול להיות שגם הוא התקשה? הרי יכול להיות שהוא רצה לשתף פעולה, אבל פשוט לא הבין מה מצפים ממנו."},{"id":"article-paragraph-924e0e4b6f7d","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אני מסביר לילד שליאו לא יודע לבצע את התרגיל הזה, ושבחרתי בפעילות כדי שנוכל לפגוש יחד תחושה שנקראת תסכול ולדבר עליה."},{"id":"article-paragraph-3c10c16e1c6a","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"כאן מתחילה מבחינתי העבודה המשמעותית."},{"id":"article-heading-6fb89cb1a823","heading":"גם הילד וגם הכלב יכולים לפגוש תסכול","text":"גם הילד וגם הכלב יכולים לפגוש תסכול"},{"id":"article-paragraph-11bb1d4c7733","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"לפעמים קל יותר לילד להבין את מה שקרה דווקא דרך הניסיון להתבונן בכלב."},{"id":"article-paragraph-25dbaa1f8318","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אפשר לשאול אותו: מה לדעתך קרה לליאו כשהוא לא הצליח להבין אותך? איך הוא הרגיש כשניסית שוב ושוב? מה לדעתך היה יכול לעזור לו?"},{"id":"article-paragraph-4fe70858bd19","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אנחנו לא יכולים לדעת בוודאות מה הכלב הרגיש, אבל אנחנו כן יכולים להתבונן בהתנהגות שלו ולחשוב על האפשרויות."},{"id":"article-paragraph-91d96b8ec972","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"ואז אנחנו חוזרים לילד."},{"id":"article-paragraph-263f71961e3b","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"מה אתה הרגשת כשהוא לא הצליח? זה הזכיר לך מצב אחר? מתי עוד אתה מרגיש ככה? מה אתה עושה בדרך כלל כשמשהו לא מצליח לך?"},{"id":"article-paragraph-ac5f567f72aa","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"כך התסכול הופך ממשהו שהילד חווה במהלך המשחק לנושא שאפשר לזהות, להבין ולדבר עליו."},{"id":"article-heading-06ae64f0e0ad","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו"},{"id":"article-paragraph-eb058068ddbd","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"זה אולי המסר המרכזי שאני מנסה להעביר לילדים."},{"id":"article-paragraph-cd2de9c28ff6","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"אנחנו לא יכולים להבטיח שלא נרגיש תסכול. זה פשוט בלתי אפשרי."},{"id":"article-paragraph-0da7a764828e","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"כולנו נפגוש שוב ושוב מצבים שבהם הדברים לא מתרחשים כפי שרצינו."},{"id":"article-paragraph-8a0187ac02ec","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"אבל אפשר לפתח את היכולת לשים לב למה שאנחנו עושים עם התחושה הזאת."},{"id":"article-paragraph-b21a85a8bc1f","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"אחת השאלות שאני אוהב לעבוד איתן היא:"},{"id":"article-paragraph-a4b7586be122","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"האם הדרך שבה אני עומד להגיב עכשיו תגרום לי להרגיש טוב יותר או פחות טוב? האם היא תגדיל את התסכול שלי, או תעזור לי להתמודד איתו?"},{"id":"article-paragraph-9f6c75541dcb","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"נחזור רגע לליאו."},{"id":"article-paragraph-d6109ed7a8a5","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"ניסינו ללמד אותו לעשות גלגול והוא לא הצליח."},{"id":"article-paragraph-08f68b26a34a","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"אפשר להתעצבן עליו, לצעוק שהוא לא מקשיב, להגיד שהוא כלב מעצבן ולהפסיק את הפעילות בכעס."},{"id":"article-paragraph-373a36ba071f","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"אבל מה יקרה אז? האם נרגיש פחות מתוסכלים? האם ליאו יבין טוב יותר מה רצינו?"},{"id":"article-paragraph-e1101df8c465","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"סביר להניח שלא. הכעס עלול רק להגביר את המתח של שנינו."},{"id":"article-paragraph-f158ddaa630f","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"לעומת זאת, אפשר לנסות משהו אחר."},{"id":"article-paragraph-05cda50fa8de","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"לעצור רגע, ללטף את ליאו אם הוא מעוניין במגע, להגיד לו \"לא נורא\", ולבחור לעשות יחד תרגיל אחר שהוא כן יודע."},{"id":"article-paragraph-1b7aaa721377","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"פתאום שנינו יכולים לחוות הצלחה. אנחנו מסיימים את הפעילות בתחושה נעימה יותר, במקום להמשיך להיאבק במשהו שלא מצליח."},{"id":"article-paragraph-ec6c3cdaa4a4","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"זאת בדיוק המיומנות שאני רוצה לעזור לילד לפתח."},{"id":"article-paragraph-a0b761d25faa","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"לא להימנע מכל קושי, ולא לוותר אוטומטית בכל פעם שמשהו לא עובד, אלא להבין מתי כדאי לנסות שוב, מתי כדאי לשנות דרך ומתי נכון לקבל שמשהו פשוט לא אפשרי כרגע."},{"id":"article-heading-6358f8298bb4","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק"},{"id":"article-paragraph-44b889b444df","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"דרך נוספת שבה אני עובד על התמודדות עם תסכול היא משחק."},{"id":"article-paragraph-f5ccc1071bf2","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"למשל, יש לי משחק שבו צריך להניח דמויות קטנות של כלבים על מבנה עץ לא יציב. זורקים קובייה, ובהתאם למספר שיוצא צריך להניח כלב על המבנה, בלי שייפול."},{"id":"article-paragraph-9ce491799eaf","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"במהלך המשחק אני יכול ליצור הפרעה קטנה ומבוקרת, למשל להזיז את המבנה כך שחלק ממנו יתפרק."},{"id":"article-paragraph-a7b11bf4ae82","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"זאת סיטואציה שיכולה לעורר הרבה תסכול."},{"id":"article-paragraph-ac7e7e68cdbe","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"הילד השקיע, ניסה להצליח, ופתאום מישהו אחר מפריע לו."},{"id":"article-paragraph-c682e9c392c7","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"כשהקשר מאפשר זאת, אפשר להשתמש ברגע הזה כדי לבדוק יחד מה קרה."},{"id":"article-paragraph-1a5714dbb31b","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"מה הרגשת כשהפלתי לך את המבנה? מה רצית לעשות? האם רצית לכעוס עליי, לצעוק או להחזיר לי?"},{"id":"article-paragraph-e43e47004728","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"ואז אנחנו חושבים על האפשרויות."},{"id":"article-paragraph-371af4d938eb","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"אפשר להתעצבן עליי ולהתחיל לריב איתי. יכול להיות שזה יוביל לכך שגם אני אתעצבן, והמשחק ייהרס לגמרי."},{"id":"article-paragraph-242e0b7259b4","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"אבל אולי אפשר להגיב אחרת. למשל, להגיד לי שזה מפריע, לבקש שאפסיק או אפילו להזמין אותי לעזור לבנות מחדש."},{"id":"article-paragraph-e87eb673f7f8","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"כך אפשר לעבור מריב ומאבק לניסיון לפתור את הבעיה."},{"id":"article-paragraph-c387d8dddb0f","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"כמובן, חשוב שההתנסות תישאר משחקית, מותאמת ונסבלת עבור הילד. אם היא פוגעת בתחושת הביטחון או מציפה אותו מעבר ליכולתו, היא כבר לא משרתת את המטרה הטיפולית."},{"id":"article-heading-a7e5aa1f0bc1","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?"},{"id":"article-paragraph-6eb46285c813","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"הפעילות עם הכלב או המשחק הם רק נקודת ההתחלה."},{"id":"article-paragraph-a7bb579d772e","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"אחרי שהילד הצליח לזהות את התסכול בתוך המפגש, אנחנו מנסים לחבר את הדברים לחיים שלו."},{"id":"article-paragraph-a5aadcb9b9b2","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"אני יכול לשאול אותו מתי לאחרונה הרגיש תסכול בבית או בבית הספר."},{"id":"article-paragraph-e82d1a300c0f","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"למשל, כשהוא רב עם חבר."},{"id":"article-paragraph-8fc7e6a5a4ab","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"החבר עשה משהו שהכעיס אותו, והוא בתגובה הרביץ לו."},{"id":"article-paragraph-35c7a34622eb","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"אנחנו יכולים לנסות להבין מה קרה שם: מה הוא רצה שיקרה? מה עורר את התסכול? האם התגובה שלו פתרה את הבעיה? האם הוא הרגיש טוב יותר אחריה, או שבסופו של דבר מצא את עצמו גם כועס, גם רב עם החבר וגם מסתבך?"},{"id":"article-paragraph-ef741a94e09e","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"או מצב אחר: אמא אמרה לו לא."},{"id":"article-paragraph-81cca862a606","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"הוא כעס, צעק ושבר משהו."},{"id":"article-paragraph-d29d80912d96","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"האם זה עזר לו לקבל את מה שרצה? מה קרה אחר כך? האם הייתה דרך אחרת שבה יכול היה לבטא את הכעס שלו מבלי לפגוע בעצמו או באחרים?"},{"id":"article-paragraph-f3371c8c7a50","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"המטרה היא לא לגרום לילד להרגיש אשם על מה שעשה, אלא לעזור לו לפתח מודעות ואפשרויות נוספות."},{"id":"article-paragraph-9efdf7def00a","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"לפעמים נגלה שהתגובה שלו רק הגבירה את התסכול המקורי. ולפעמים הוא ילמד שדווקא בקשת עזרה, שיחה, התרחקות רגעית או שינוי בתוכנית יכולים לעזור לו להתמודד טוב יותר."},{"id":"article-heading-09661640b920","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?"},{"id":"article-paragraph-12efdbfa18c8","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"אני חושב שאחת הטעויות שאנחנו יכולים לעשות כמבוגרים היא לנסות למנוע מהילדים שלנו כל תסכול."},{"id":"article-paragraph-f5a3bc9afc24","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"זה מובן. קשה לנו לראות את הילדים שלנו מאוכזבים, עצובים או כועסים, ולפעמים הרבה יותר פשוט לפתור עבורם את הבעיה."},{"id":"article-paragraph-02f3e85c5443","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"אבל אם נפתור עבורם כל קושי, נפספס הזדמנויות שבהן הם יכולים לגלות שהם מסוגלים להתמודד."},{"id":"article-paragraph-68881b994a5c","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"מצד שני, גם להשאיר ילד לבד עם תסכול גדול מדי לא בהכרח יעזור לו לפתח את היכולת הזאת."},{"id":"article-paragraph-1ed6da55fc17","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"המפתח נמצא במידה רבה בקשר ובתמיכה שאנחנו מספקים."},{"id":"article-paragraph-23699e00b051","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"כשהילד מתוסכל, אפשר קודם כול לתת מקום למה שהוא מרגיש. להבין שהוא באמת רצה משהו, שזה באמת מאכזב או שהמשימה באמת קשה לו. לעזור לו לתת שם לרגש שהוא חווה עכשיו - \"אני רואה שאתה מתוסכל, זה באמת יכול להיות מאוד מתסכל כשאנחנו לא מקבלים את מה שרצינו\"."},{"id":"article-paragraph-ca646930d230","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"זה לא אומר שחייבים לוותר על הגבול שהצבנו."},{"id":"article-paragraph-4e7987c93310","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"אפשר להבין את הכעס שלו ובו בזמן להישאר עם ההחלטה שלנו."},{"id":"article-paragraph-8752810bc687","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"כשהילד רגוע מספיק, אפשר לחשוב איתו יחד על מה שקרה. מה הוא הרגיש? מה ניסה להשיג? האם הדרך שבה הגיב עזרה לו? ומה יוכל לעשות אחרת בפעם הבאה?"},{"id":"article-paragraph-3c0131ab7099","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"חשוב גם לזכור שלא תמיד צריך ללמד משהו באותו רגע."},{"id":"article-paragraph-553014aeabad","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"כשהילד מוצף מאוד, לפעמים הוא זקוק בעיקר למבוגר שיהיה איתו, יעזור לו להירגע ולא יהפוך את התסכול המקורי לעוד מאבק."},{"id":"article-paragraph-cbfeae5435e3","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"אחר כך, כשהוא פנוי לכך, אפשר לחזור ולדבר."},{"id":"article-heading-501269f79116","heading":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו","text":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו"},{"id":"article-paragraph-53c6d0227ac9","heading":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו","text":"תסכול הוא חלק מהחיים. הוא מופיע בכל גיל, בכל מערכת יחסים וכמעט בכל תחום."},{"id":"article-paragraph-213be57ccd62","heading":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו","text":"אנחנו לא יכולים להבטיח לילדים שלנו שהכול יצליח להם, שכולם יסכימו איתם או שתמיד יקבלו את מה שהם רוצים."},{"id":"article-paragraph-279ee66a858b","heading":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו","text":"אבל אנחנו כן יכולים לעזור להם לפתח את היכולת להתמודד עם מציאות שלא תמיד מתאימה לרצונות שלהם."},{"id":"article-paragraph-5a8238c6ad4e","heading":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו","text":"בטיפול רגשי בעזרת כלבים, אני מנסה ליצור הזדמנויות שבהן ילדים יכולים לפגוש תסכול, לזהות אותו, להבין איך הם מגיבים אליו ולגלות דרכים נוספות להתמודד."},{"id":"article-paragraph-0c984220e00d","heading":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו","text":"אבל כל זה מתחיל בקשר."},{"id":"article-paragraph-55ee3db083e1","heading":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו","text":"רק כשהילד מרגיש מספיק בטוח, אפשר לאפשר לו להתמודד עם קושי מבלי שהכישלון יהפוך לאיום על תחושת הערך שלו או על הקשר הטיפולי."},{"id":"article-paragraph-8df1f87b9d84","heading":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו","text":"המטרה היא לא שילדים יפסיקו להרגיש תסכול. המטרה היא שהם יגלו שגם כשהדברים לא מסתדרים כפי שרצו, הם מסוגלים להתמודד, למצוא דרכים אחרות ולהמשיך הלאה."}]},{"title":"סבלנות ודחיית סיפוקים אצל ילדים - איך מפתחים את היכולת לחכות?","url":"https://derech-hakelev.com/pages/articles/patience-delayed-gratification-children/","entries":[{"id":"article-title-a66b02bb2b08","heading":"תחילת המאמר","text":"סבלנות ודחיית סיפוקים אצל ילדים - איך מפתחים את היכולת לחכות?"},{"id":"article-paragraph-8a8f735cb3da","heading":"פתיחת המאמר","text":"הילד מתקשה לחכות לתור שלו? רוצה לקבל הכול כאן ועכשיו? מתעצבן כשאומרים לו שצריך לחכות, או מתקשה להתאפק גם כשהוא יודע שכדאי לו?"},{"id":"article-paragraph-05383ddf780f","heading":"פתיחת המאמר","text":"סבלנות ודחיית סיפוקים הן יכולות שאנחנו משתמשים בהן כמעט בכל תחום בחיים. הן מאפשרות לנו להתמודד עם רצונות שלא מתממשים מיד, להשקיע מאמץ במטרות ארוכות טווח ולהתנהל גם כשהדברים לא קורים בדיוק בקצב שהיינו רוצים."},{"id":"article-paragraph-060081fc6207","heading":"פתיחת המאמר","text":"אבל אנחנו לא נולדים עם היכולות האלה כשהן מפותחות."},{"id":"article-paragraph-27f0c8e963e2","heading":"פתיחת המאמר","text":"תינוק שרעב רוצה לאכול עכשיו. הוא לא מבין שאמא מכינה לו בקבוק ושבעוד כמה דקות האוכל יהיה מוכן. גם אם נסביר לו שכדאי לחכות בסבלנות, זה לא ממש יעזור."},{"id":"article-paragraph-3768995c18e8","heading":"פתיחת המאמר","text":"עם השנים, ככל שאנחנו מתפתחים, אנחנו לומדים בהדרגה להתמודד עם ההמתנה, לדחות רצונות מסוימים ולבחור לפעמים במה שישתלם לנו יותר בהמשך."},{"id":"article-paragraph-a6d4f858f292","heading":"פתיחת המאמר","text":"אצל חלק מהילדים היכולת הזאת מתפתחת בקלות יחסית, ואצל אחרים היא דורשת יותר זמן, תמיכה והתנסות."},{"id":"article-paragraph-86ff6a528283","heading":"פתיחת המאמר","text":"אז איך אפשר לעזור לילדים לפתח סבלנות ודחיית סיפוקים? ואיך אפשר לעבוד על היכולות האלה דווקא דרך טיפול רגשי בעזרת כלבים?"},{"id":"article-heading-37c4448cbb20","heading":"מה ההבדל בין סבלנות לדחיית סיפוקים?","text":"מה ההבדל בין סבלנות לדחיית סיפוקים?"},{"id":"article-paragraph-270e0193fb71","heading":"מה ההבדל בין סבלנות לדחיית סיפוקים?","text":"סבלנות היא היכולת לשאת המתנה, קושי או עיכוב מבלי לאבד מיד את היכולת להתמודד עם המצב."},{"id":"article-paragraph-45d3731c8860","heading":"מה ההבדל בין סבלנות לדחיית סיפוקים?","text":"למשל, לחכות בתור, להמשיך לנסות משהו שלא מצליח בפעם הראשונה או להתמודד עם מצב שבו הדברים מתקדמים לאט יותר ממה שהיינו רוצים."},{"id":"article-paragraph-bbf289534add","heading":"מה ההבדל בין סבלנות לדחיית סיפוקים?","text":"דחיית סיפוקים היא יכולת מעט שונה: היכולת לוותר על סיפוק מיידי, או לדחות אותו, כדי להשיג משהו אחר בהמשך."},{"id":"article-paragraph-386f0d303c01","heading":"מה ההבדל בין סבלנות לדחיית סיפוקים?","text":"למשל, ילד שמעדיף לשמור את דמי הכיס שלו במשך כמה שבועות כדי לקנות משהו שהוא מאוד רוצה, במקום לבזבז אותם מיד על משהו קטן."},{"id":"article-paragraph-325c2d0c4e75","heading":"מה ההבדל בין סבלנות לדחיית סיפוקים?","text":"שתי היכולות קשורות לוויסות עצמי, לשליטה בדחפים וליכולת שלנו לפעול בהתאם למטרות שלנו, גם כשיש משהו שמושך אותנו לעשות אחרת באותו רגע."},{"id":"article-heading-2cd5842218e4","heading":"למה סבלנות ודחיית סיפוקים כל כך חשובות?","text":"למה סבלנות ודחיית סיפוקים כל כך חשובות?"},{"id":"article-paragraph-29b80e5b19f2","heading":"למה סבלנות ודחיית סיפוקים כל כך חשובות?","text":"לפעמים אנחנו חושבים על סבלנות בעיקר בהקשר של ילדים: לחכות בתור, לא להתפרץ לדברי אחרים או להמתין עד שההורה יתפנה."},{"id":"article-paragraph-61e2112902f8","heading":"למה סבלנות ודחיית סיפוקים כל כך חשובות?","text":"אבל ככל שאנחנו מתבגרים, אנחנו מבינים עד כמה היכולת הזאת משמעותית כמעט בכל תחום בחיים."},{"id":"article-paragraph-f4893d137b93","heading":"למה סבלנות ודחיית סיפוקים כל כך חשובות?","text":"בלימודים, אנחנו צריכים להשקיע ולהתאמץ גם כשלא רואים תוצאה מיידית. בעבודה, אנחנו צריכים לפעמים להתמיד לאורך זמן עד שמגיעים להישגים. בזוגיות ובמערכות יחסים ובטח שבהורות, אנחנו נדרשים להקשיב, להתפשר ולהתמודד עם העובדה שלא תמיד הרצונות שלנו מתממשים מיד."},{"id":"article-paragraph-933e93ffe928","heading":"למה סבלנות ודחיית סיפוקים כל כך חשובות?","text":"היכולת לחכות, להתאפק ולהתמיד גם כשקשה מאפשרת לנו לפעול בהתאם למה שחשוב לנו, ולא רק בהתאם למה שאנחנו רוצים באותו רגע."},{"id":"article-paragraph-faed7e507792","heading":"למה סבלנות ודחיית סיפוקים כל כך חשובות?","text":"אבל חשוב לי להדגיש: סבלנות היא לא היכולת לשתוק, לציית או לוותר על הרצונות שלנו. היא היכולת להתמודד עם ההמתנה ועם הקושי, ולבחור כיצד לפעול."},{"id":"article-heading-f8837502338a","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?"},{"id":"article-paragraph-830871326494","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"כמו יכולות רגשיות והתפתחותיות רבות, גם סבלנות ודחיית סיפוקים מתפתחות בהדרגה."},{"id":"article-paragraph-113f7c8fc482","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"בתחילת החיים, תינוקות תלויים מאוד במבוגרים כדי לספק את הצרכים שלהם ולעזור להם להירגע. כשהם רעבים, עייפים או לא מרגישים בנוח, הם זקוקים למישהו שיענה לצורך שלהם."},{"id":"article-paragraph-0e89ff567c8c","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"עם הזמן, ילדים מתחילים להבין שלא כל דבר יכול לקרות מיד."},{"id":"article-paragraph-82bd1f3ffeb4","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"בהתחלה הם מסוגלים להמתין לזמן קצר מאוד, ובהמשך יכולים ללמוד לחכות יותר, להתמודד עם הסחות דעת ולמצוא דרכים שיעזרו להם בזמן ההמתנה."},{"id":"article-paragraph-405f61166b15","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"ההתפתחות הזאת קשורה בין היתר להבשלה של יכולות כמו ויסות רגשי, קשב, תכנון ועיכוב תגובה."},{"id":"article-paragraph-5094f39bf5a2","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"סקירה מחקרית רחבה שפורסמה בשנת 2023 בכתב העת Developmental Review, והתבססה על 136 מאמרי סקירה ומטא-אנליזות, בחנה את התפתחות הוויסות העצמי מהינקות ועד גיל ההתבגרות."},{"id":"article-paragraph-0d478539757b","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"הסקירה מתארת כיצד הוויסות מתפתח מתהליך שתלוי מאוד בעזרת המבוגרים בתחילת החיים, ליכולת עצמאית ומורכבת יותר ככל שהילד גדל. היא גם מדגישה את תפקידם של ההורים, המורים והסביבה החברתית בהתפתחות היכולת הזאת."},{"id":"article-paragraph-69d9e62359cd","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"ההתפתחות לא מתרחשת אצל כולם באותו הקצב."},{"id":"article-paragraph-ace4b9be5fc0","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"גם הסביבה והקשרים של הילד משפיעים על התהליך. ילד שמקבל תמיכה כשהוא מתקשה ושיש לו הזדמנויות מותאמות להתמודד עם המתנה, יכול לפתח בהדרגה יותר כלים להתמודדות."},{"id":"article-paragraph-5868d1e6bd09","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"ולא פחות חשוב, גם אצל מבוגרים היכולת הזאת אינה מושלמת. כולנו מכירים רגעים שבהם קשה לנו להתאפק, לחכות או לדחות משהו שאנחנו מאוד רוצים."},{"id":"article-paragraph-bc453db71216","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"לקריאה נוספת: הגישה ההתפתחותית־היקשרותית בטיפול בעזרת כלבים – על החשיבות של קשר וביטחון בהתפתחות הרגשית של ילדים."},{"id":"article-heading-5e04db0d9591","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?"},{"id":"article-paragraph-62a0064a7f2b","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"לא כל ילד שמתקשה לחכות הוא ילד שיש לו בעיה."},{"id":"article-paragraph-aa9eb998ae30","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"ילד קטן שמתקשה לחכות לממתק או מתעצבן כשצריך להפסיק משחק מתנהג לעיתים באופן שמתאים לגילו ולשלב ההתפתחותי שלו."},{"id":"article-paragraph-4edb86fec583","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"גם ילדים גדולים יותר יכולים להתקשות במיוחד כשהם עייפים, רעבים, מתרגשים או נמצאים במצב רגשי מורכב."},{"id":"article-paragraph-f0c30ee4981b","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"השאלה היא עד כמה הקושי חוזר על עצמו ועד כמה הוא משפיע על החיים של הילד."},{"id":"article-paragraph-b7dac89c83bc","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"למשל, ילד שמתקשה כמעט תמיד לחכות לתורו, מתפרץ שוב ושוב לדברי אחרים, מתקשה להשלים משימות שדורשות התמדה או מגיב בעוצמה גדולה בכל פעם שלא מקבל מיד את מה שרצה."},{"id":"article-paragraph-3114dd09157f","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"אם הקשיים האלה פוגעים באופן משמעותי בלימודים, בחברויות או בהתנהלות בבית, כדאי להבין מה עומד מאחוריהם."},{"id":"article-paragraph-67ee02444c77","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"לפעמים מדובר בקושי בוויסות רגשי, לפעמים בקשיי קשב או בתפקודים ניהוליים, ולפעמים יש גורמים אחרים שמשפיעים על יכולתו של הילד להמתין."},{"id":"article-paragraph-fd9b3222f11d","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"המטרה היא לא לצפות מכל ילד להיות סבלני כל הזמן, אלא להבין מה מתאים לשלב ההתפתחותי שלו ואיך אפשר לעזור לו להתקדם."},{"id":"article-paragraph-bcca9f8e6961","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"אפשר לקרוא על כך גם במאמר ויסות רגשי אצל ילדים – איך טיפול בעזרת כלבים יכול לעזור?."},{"id":"article-heading-dcf53e94505c","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"מה אפשר ללמוד ממבחן המרשמלו?"},{"id":"article-paragraph-24d74288d0f4","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"אחד הניסויים המוכרים ביותר בפסיכולוגיה הוא מבחן המרשמלו, שפותח במסגרת מחקריו של הפסיכולוג וולטר מישל."},{"id":"article-paragraph-c1f6b337fc32","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"בניסוי המפורסם, הציעו לילדים לקבל ממתק אחד מיד, או להמתין זמן מסוים ולקבל שני ממתקים בהמשך."},{"id":"article-paragraph-265458798d23","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"הילדים היו צריכים להתמודד עם בחירה: האם לקחת עכשיו משהו שהם רוצים, או לחכות כדי לקבל יותר אחר כך?"},{"id":"article-paragraph-718874700686","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"החוקרים התעניינו לא רק בשאלה כמה זמן הילדים מצליחים לחכות, אלא גם בדרכים שבהן הם מתמודדים עם ההמתנה."},{"id":"article-paragraph-190511dab048","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"חלק מהילדים ניסו להסיח את דעתם, חלקם הסתכלו לכיוון אחר, וחלקם מצאו דרכים שונות להעביר את הזמן."},{"id":"article-paragraph-4e3f36a2b7cb","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"הניסוי הזה הפך למוכר מאוד, בין היתר משום שמחקרים מוקדמים מצאו קשר בין היכולת לחכות בילדות לבין הישגים בהמשך החיים."},{"id":"article-paragraph-8ca77ec92fe1","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"אבל מחקרי המשך הציגו תמונה מורכבת יותר."},{"id":"article-paragraph-70dc5771fa55","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"בשנת 2018 פורסם מחקר שבחן מחדש את הקשר בין דחיית סיפוקים בילדות לבין הישגים בגיל ההתבגרות. החוקרים מצאו שהקשר נחלש משמעותית כאשר מביאים בחשבון את הרקע המשפחתי, היכולות המוקדמות והסביבה שבה הילד גדל."},{"id":"article-paragraph-fb2fab12944c","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"במחקר נוסף שפורסם בשנת 2024, ועקב אחר 702 משתתפים עד גיל 26, נמצא שהביצועים במבחן המרשמלו בילדות לא ניבאו באופן מהימן את ההישגים, הבריאות וההתנהגות בבגרות."},{"id":"article-paragraph-8cb76bd1c504","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"המשמעות היא שהמבחן לא קובע את עתידו של הילד, ושהיכולת לחכות מושפעת גם מהסביבה ומהנסיבות."},{"id":"article-paragraph-3a3a5c422796","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"מבחינתי, הדבר המעניין ביותר במבחן הוא דווקא האפשרות להשתמש בו כדי להבין מה עוזר לילד לחכות, מה מקשה עליו ואילו אסטרטגיות הוא יכול לפתח."},{"id":"article-heading-6231c7cf21df","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?"},{"id":"article-paragraph-b2eb7dbf37ab","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"אחת הדרכים שאני אוהב לעבוד על היכולות האלה היא דווקא דרך הכלבים."},{"id":"article-paragraph-12af21687471","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"כשחושבים על זה, גם לכלבים לא תמיד קל לחכות."},{"id":"article-paragraph-8580d9ef323c","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"הם רוצים להגיע לאוכל, לרוץ אחרי כדור, לקבל חטיף, לצאת לטיול או לגשת למשהו שמעניין אותם."},{"id":"article-paragraph-bf5d2ec7d0c1","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"וכאן נוצרת הזדמנות מעניינת: במקום להסביר לילד רק למה חשוב לחכות בסבלנות, אנחנו יכולים להתנסות בזה יחד עם הכלבים."},{"id":"article-paragraph-74fc54bd10ba","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"במהלך הפעילות הילד גם לומד לעזור לכלב להתמודד עם ההמתנה, וגם מקבל הזדמנות להתבונן בקושי שלו עצמו."},{"id":"article-heading-0ff7b63115e0","heading":"מתחילים מ\"להישאר\"","text":"מתחילים מ\"להישאר\""},{"id":"article-paragraph-7f6f3fead9ba","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"אחת הפעילויות הראשונות שאנחנו עושים היא עבודה על הפקודה \"להישאר\"."},{"id":"article-paragraph-6ebf3aaf868d","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"אנחנו מבקשים מהכלב לשבת או לשכב, ולאחר מכן להישאר במקום בזמן שאנחנו מתרחקים ממנו."},{"id":"article-paragraph-1224ea4351f7","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"בהתחלה מתרחקים ממש מעט, חוזרים אל הכלב ומחזקים אותו על ההצלחה. בהדרגה אפשר להגדיל את המרחק ואת משך ההמתנה, בהתאם ליכולת שלו."},{"id":"article-paragraph-18378cf28e61","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"לכאורה מדובר בתרגיל אילוף פשוט, אבל אפשר ללמוד ממנו לא מעט."},{"id":"article-paragraph-af611c6a83e7","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"לכלב לא תמיד קל להישאר במקום. הוא אולי רוצה ללכת אחרי הילד, להתקרב אליו או להתחיל לשחק."},{"id":"article-paragraph-81b751635b2e","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"הילד צריך ללמוד להתקדם בהדרגה, לתת לכלב הוראות ברורות ולא לצפות ממנו להצליח מיד במשימה קשה מדי."},{"id":"article-paragraph-206ad02bb1b3","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"גם הילד עצמו נדרש לסבלנות."},{"id":"article-paragraph-12f12dc9548e","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"לפעמים הכלב קם לפני הזמן, לפעמים צריך לחזור על התרגיל, ולפעמים ההתקדמות איטית יותר ממה שהילד ציפה."},{"id":"article-paragraph-5c0445b25191","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"כך אנחנו בעצם עובדים על סבלנות משני הכיוונים: גם של הכלב וגם של הילד."},{"id":"article-heading-58d8704bfd73","heading":"עוברים ל\"לא לגעת\"","text":"עוברים ל\"לא לגעת\""},{"id":"article-paragraph-59f3007f3ae4","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"אחרי שהילד והכלב מתנסים בהמתנה, אפשר לעבור לפעילות נוספת: \"לא לגעת\"."},{"id":"article-paragraph-730fb77dcdb3","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"אנחנו מניחים חטיף במקום נגיש לכלב ומבקשים ממנו להמתין ולא לקחת אותו עד שניתן לו אישור."},{"id":"article-paragraph-2697fd4e5570","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"ככל שהכלב לומד את התרגיל, אפשר להעלות בהדרגה את רמת הקושי. למשל, להניח את החטיף קרוב יותר אליו או על כף הרגל שלו, אם הוא כבר מכיר את התרגיל ומרגיש איתו בנוח."},{"id":"article-paragraph-0533dac0740f","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"אפשר גם להכין יחד ציור מאוכל הכלבים בזמן שהכלב מחכה, ובסיום לתת לו אישור לאכול את הציור בהנאה."},{"id":"article-paragraph-97a706d8da74","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"מבחינת הכלב, יש כאן משהו שהוא רוצה מאוד, נמצא ממש מולו, ובכל זאת הוא נדרש לחכות."},{"id":"article-paragraph-c5c342d98c71","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"זה מזכיר לא מעט מצבים שאנחנו פוגשים בחיים."},{"id":"article-paragraph-271122ea7e94","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"לפעמים אנחנו רוצים משהו עכשיו, אבל יודעים שכדאי לחכות. לפעמים אנחנו צריכים להתאפק כדי להגיע למטרה גדולה יותר."},{"id":"article-paragraph-0345cde067d9","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"אחד הדברים המעניינים בפעילות הוא לראות איך הילד מגיב כשהכלב מתקשה."},{"id":"article-paragraph-9c35389e948f","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"האם הוא מתעצבן כשהכלב לוקח את החטיף לפני הזמן? האם הוא מוכן להתחיל שוב? האם הוא מבין שצריך להקל על הכלב כדי לעזור לו להצליח?"},{"id":"article-paragraph-ba020c8c191f","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"כך הפעילות לא עוסקת רק ביכולת של הכלב לדחות סיפוקים, אלא גם ביכולת של הילד להתמודד עם תהליך שמצריך סבלנות."},{"id":"article-heading-634ff2bf809f","heading":"מה קורה כשמוסיפים הסחות דעת?","text":"מה קורה כשמוסיפים הסחות דעת?"},{"id":"article-paragraph-3516fd1cf136","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"בשלב הבא אפשר להכניס לתרגילים גם גירויים שמקשים על ההמתנה."},{"id":"article-paragraph-6470c1790748","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"למשל, בזמן שהכלב מתרגל \"להישאר\", אני יכול לגלגל כדור במרחק מסוים או ליצור גירוי אחר שמושך את תשומת הלב שלו."},{"id":"article-paragraph-e1297d571567","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"עכשיו, כשהכדור מתגלגל לידו, הרבה יותר קשה לו להתאפק."},{"id":"article-paragraph-e9ffdf06da9d","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"כמובן, אנחנו מעלים את רמת הקושי בהדרגה ומתאימים אותה לכלב. המטרה היא לא להכשיל או להלחיץ אותו, אלא לאפשר לו ללמוד ולהצליח."},{"id":"article-paragraph-c7899be591cd","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"אחרי ההתנסות אנחנו מדברים על מה שקרה."},{"id":"article-paragraph-365175cd79da","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"למה היה לכלב קל יותר לחכות קודם? מה השתנה כשהכדור הופיע? האם יש גם דברים שמקשים עלינו לחכות?"},{"id":"article-paragraph-abc9e3e4b141","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"למשל, הרבה יותר קשה לחכות לממתק כשהוא מונח ממש מולנו, מאשר כשהוא נמצא בארון. קשה יותר להתרכז בשיעורי הבית כשהטלפון כל הזמן מצפצף לידנו."},{"id":"article-paragraph-1cc385f9da02","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"וכאן אנחנו מתחילים לחשוב לא רק על היכולת להתאפק, אלא גם על הדברים שמשפיעים עליה."},{"id":"article-heading-bb0aa1b0df90","heading":"מה עוזר לנו לחכות בסבלנות?","text":"מה עוזר לנו לחכות בסבלנות?"},{"id":"article-paragraph-4eb03652da74","heading":"מה עוזר לנו לחכות בסבלנות?","text":"אחרי שהילד התנסה בפעילויות עם הכלבים, אנחנו מנסים להבין יחד מה יכול לעזור גם לו."},{"id":"article-paragraph-01a6c8baaad6","heading":"מה עוזר לנו לחכות בסבלנות?","text":"אחת האפשרויות היא הסחת דעת."},{"id":"article-paragraph-b3fc5b4c5e75","heading":"מה עוזר לנו לחכות בסבלנות?","text":"לפעמים, כשאנחנו מחכים למשהו, עצם המחשבה עליו הופכת את ההמתנה לקשה יותר. אם אנחנו מוצאים משהו אחר להתעסק בו, הזמן יכול לעבור בקלות רבה יותר."},{"id":"article-paragraph-5ab58395b7ad","heading":"מה עוזר לנו לחכות בסבלנות?","text":"מחקר שפורסם בשנת 2023 בחן 144 ילדים בני כחמש, בזמן שביצעו משימה של דחיית סיפוקים."},{"id":"article-paragraph-a57ec920f2fa","heading":"מה עוזר לנו לחכות בסבלנות?","text":"החוקרים התבוננו לא רק בשאלה האם הילדים הצליחו לחכות, אלא גם בהתנהגות שלהם בזמן ההמתנה: תנועות הגוף, דיבור עצמי, מידת ההתמקדות בפרס והדרכים שבהן ניסו להתמודד עם הרצון לקבל אותו."},{"id":"article-paragraph-09130dac8a59","heading":"מה עוזר לנו לחכות בסבלנות?","text":"המחקר הראה שיש משמעות גם לאופן שבו הילד מתמודד בזמן ההמתנה, ולא רק למשך הזמן שהוא מצליח לחכות."},{"id":"article-paragraph-0e8cb8ab4672","heading":"מה עוזר לנו לחכות בסבלנות?","text":"וזה מתחבר מאוד לעבודה שלי עם הילדים. אני רוצה להבין לא רק אם הילד הצליח להתאפק, אלא איך הוא עשה את זה ומה עזר לו."},{"id":"article-paragraph-578cabb6ca49","heading":"מה עוזר לנו לחכות בסבלנות?","text":"אפשרות נוספת היא חלוקת הזמן לחלקים קטנים."},{"id":"article-paragraph-918e0892ff58","heading":"מה עוזר לנו לחכות בסבלנות?","text":"לילד עשוי להיות קשה לחשוב שהוא צריך לחכות עוד חצי שעה. אבל אם נחלק את הזמן לכמה שלבים, ונתמקד בכל פעם בחלק קטן, ההמתנה עשויה להרגיש אפשרית יותר."},{"id":"article-paragraph-bfab3a1d3d72","heading":"מה עוזר לנו לחכות בסבלנות?","text":"גם הבנת המטרה יכולה לעזור."},{"id":"article-paragraph-b9a53c943f2f","heading":"מה עוזר לנו לחכות בסבלנות?","text":"כשאנחנו יודעים למה אנחנו מחכים ומה אנחנו עשויים להרוויח מההמתנה, לפעמים קל יותר להתאפק."},{"id":"article-paragraph-77c4a2cd94bb","heading":"מה עוזר לנו לחכות בסבלנות?","text":"ילד שחוסך כסף כדי לקנות משהו שהוא מאוד רוצה עשוי למצוא יותר מוטיבציה לא לבזבז אותו מיד. ילד שרוצה להצליח במשימה מסוימת עשוי להיות מוכן להשקיע בה יותר זמן כשהוא מבין מה הוא מנסה להשיג."},{"id":"article-paragraph-7488e6c1fb93","heading":"מה עוזר לנו לחכות בסבלנות?","text":"אבל לא תמיד צריך רק להתאמץ יותר."},{"id":"article-paragraph-878a7ea94fde","heading":"מה עוזר לנו לחכות בסבלנות?","text":"לפעמים הדרך הטובה ביותר להתמודד עם פיתוי היא דווקא לשנות את הסביבה: להרחיק את הדבר שמסיח את דעתנו, לבחור פעילות אחרת בזמן ההמתנה או לבקש עזרה ממישהו."},{"id":"article-heading-fa4b9958aa8f","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"מבחן המרשמלו בתוך המפגש הטיפולי"},{"id":"article-paragraph-d4b25f6c8177","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"אחת הפעילויות שאני משלב לפעמים היא גרסה משחקית של מבחן המרשמלו."},{"id":"article-paragraph-26f451bf3fd0","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"אני יכול להציע לילד עוגייה אחת עכשיו, או שתי עוגיות אם יבחר לחכות זמן קצר בזמן שאני יוצא מהחדר או מתרחק, בהתאם לגילו ולמידת הביטחון שלו."},{"id":"article-paragraph-29eec34c521a","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"הילד יכול לבחור אם להמתין או לקחת את העוגייה מיד."},{"id":"article-paragraph-9780602781f1","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"אבל מבחינתי, השאלה המעניינת אינה רק אם הוא הצליח לחכות."},{"id":"article-paragraph-e2cee84f7d4e","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"אני רוצה להבין מה קרה במהלך ההמתנה."},{"id":"article-paragraph-fb34934002df","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"האם היה לו קשה? האם הוא חשב כל הזמן על העוגייה? האם ניסה להעסיק את עצמו במשהו אחר? האם עזר לו לדעת שבסוף יקבל שתי עוגיות?"},{"id":"article-paragraph-a9870e2c02d1","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"גם אם הוא בחר לא לחכות, זאת יכולה להיות הזדמנות לשיחה."},{"id":"article-paragraph-9a525b4c781c","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"אנחנו יכולים לחשוב יחד מה היה עוזר לו, מה הפך את ההמתנה לקשה, והאם היה רוצה לנסות דרך אחרת בפעם הבאה."},{"id":"article-paragraph-9838539802ef","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"המטרה היא לא לתת לילד ציון על כוח הרצון שלו, אלא להשתמש במשחק כדי להכיר טוב יותר את הדרך שבה הוא מתמודד עם רצונות והמתנה."},{"id":"article-heading-8c49edd839fb","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"איך מחברים את ההתנסות לחיים של הילד?"},{"id":"article-paragraph-5adf51f94757","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"הפעילויות עם הכלבים והמשחקים הן רק חלק מהתהליך."},{"id":"article-paragraph-f1b16115e64a","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"אחרי שהילד התנסה בהמתנה ובדחיית סיפוקים, אנחנו מנסים לחבר את הדברים למצבים שהוא פוגש ביום-יום."},{"id":"article-paragraph-b0802dfe75d6","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"למשל, ילד שמתקשה לחכות לתורו במשחק עם חברים."},{"id":"article-paragraph-759d2518a643","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"מה הוא מרגיש כשהוא צריך לחכות? מה מקשה עליו? האם יש משהו שהוא יכול לעשות בזמן ההמתנה כדי שיהיה לו קל יותר?"},{"id":"article-paragraph-67db5358b167","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"או ילד שרוצה לקבל משהו מההורים שלו מיד, ומתקשה להתמודד עם זה שאומרים לו שיצטרך לחכות."},{"id":"article-paragraph-802f91e71543","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"אנחנו יכולים לחשוב יחד מה הוא יכול לעשות במקום להתעצבן, האם יש דרך להעביר את הזמן, והאם כדאי לחלק את ההמתנה לשלבים."},{"id":"article-paragraph-76d7b9158e99","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"אפשר לדבר גם על הצלחות."},{"id":"article-paragraph-92191ad5dce9","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"מתי הצלחת לחכות למשהו שרצית מאוד? איך עשית את זה? מה עזר לך? איך הרגשת אחר כך?"},{"id":"article-paragraph-bea36e148f84","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"לפעמים דווקא הזיכרון של הצלחות קודמות עוזר לילד להבין שיש לו יכולת להתמודד, גם אם לא תמיד קל לו להשתמש בה."},{"id":"article-paragraph-a6ef540e4215","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"כשההמתנה מעוררת כעס או ויתור, היא גם מתחברת לנושא רחב יותר של התמודדות עם תסכול אצל ילדים. במאמר הזה אני מרחיב על הדרך שבה אפשר לעבוד עם ילדים על תחושת התסכול ועל הבחירה כיצד להגיב אליה."},{"id":"article-heading-222c10cf7880","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?"},{"id":"article-paragraph-281e60388d0b","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"אחד הדברים החשובים הוא לזכור שמדובר ביכולת שמתפתחת, ולא במשהו שאפשר פשוט לדרוש מהילד לעשות."},{"id":"article-paragraph-8233cf1f0090","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"כשאנחנו אומרים לילד \"תהיה סבלני\", אנחנו לא בהכרח נותנים לו את הכלים שיעזרו לו לחכות."},{"id":"article-paragraph-b6aaf05b2e7b","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"במקום זאת, אפשר לעזור לו בצורה מותאמת."},{"id":"article-paragraph-e405ca727c07","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"למשל, להתחיל מהמתנות קצרות שהוא מסוגל לעמוד בהן, ובהדרגה לאפשר לו להתנסות בהמתנות ארוכות יותר."},{"id":"article-paragraph-080ebf9f7272","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"אפשר להכין אותו מראש למה שעומד לקרות, להסביר כמה זמן יצטרך לחכות ולעזור לו למצוא משהו לעשות בזמן הזה."},{"id":"article-paragraph-1cfa9786b12e","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"אפשר גם לתת מקום לקושי שלו."},{"id":"article-paragraph-4a3f210d9016","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"\"אני יודע שאתה ממש רוצה את זה עכשיו. זה באמת קשה לחכות. בוא נחשוב מה יכול לעזור לך בינתיים.\""},{"id":"article-paragraph-7a728bc8e954","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"לא חייבים להיענות מיד לכל רצון, אבל גם לא צריך להפוך כל המתנה למבחן כוח רצון."},{"id":"article-paragraph-98a68b0d70bc","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"לפעמים הילד זקוק לעזרה שלנו כדי להתמודד עם הקושי."},{"id":"article-paragraph-8d6231e0a47e","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"וכדאי לשים לב גם להצלחות הקטנות: כשהוא הצליח לחכות עוד רגע, כשהתאפק למרות שהיה לו קשה, או כשהצליח להשקיע זמן ומאמץ במשהו שלא נתן לו סיפוק מיידי."},{"id":"article-paragraph-6fd042e27693","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"אלה הזדמנויות לעזור לו לזהות את הכוחות והיכולות שמתפתחים אצלו."},{"id":"article-heading-a778e20f590c","heading":"לסיכום - ללמוד לחכות, ולא רק להתאפק","text":"לסיכום - ללמוד לחכות, ולא רק להתאפק"},{"id":"article-paragraph-1238d6f3910e","heading":"לסיכום - ללמוד לחכות, ולא רק להתאפק","text":"סבלנות ודחיית סיפוקים הן יכולות חשובות שמלוות אותנו לאורך כל החיים."},{"id":"article-paragraph-b970da1b9316","heading":"לסיכום - ללמוד לחכות, ולא רק להתאפק","text":"הן מאפשרות לנו להתמיד, להשקיע, להתמודד עם קשיים ולפעול גם למען מטרות שלא נותנות לנו תוצאה מיידית."},{"id":"article-paragraph-856ab38fea7f","heading":"לסיכום - ללמוד לחכות, ולא רק להתאפק","text":"אבל היכולות האלה לא מופיעות בבת אחת. הן מתפתחות בהדרגה, בתוך קשר, בעזרת התנסות ותמיכה."},{"id":"article-paragraph-6acedeb75526","heading":"לסיכום - ללמוד לחכות, ולא רק להתאפק","text":"בטיפול רגשי בעזרת כלבים, אני אוהב להשתמש בפעילויות כמו \"להישאר\" ו\"לא לגעת\" כדי לאפשר לילדים להתנסות בהמתנה, לראות איך הכלבים מתמודדים איתה ולחשוב יחד על מה שעוזר ומה שמקשה."},{"id":"article-paragraph-de3fbc416c2e","heading":"לסיכום - ללמוד לחכות, ולא רק להתאפק","text":"משם אנחנו מנסים לקחת את הדברים למצבים האמיתיים שהילד פוגש בבית, בבית הספר ועם חברים."},{"id":"article-paragraph-baecf61fcc62","heading":"לסיכום - ללמוד לחכות, ולא רק להתאפק","text":"המטרה היא לא שהילד יצליח להתאפק תמיד, אלא שהוא יפתח בהדרגה את היכולת להתמודד עם ההמתנה, להבין מה עוזר לו ולבחור מתי כדאי לחכות גם כשמשהו אחר מושך אותו לפעול מיד."},{"id":"article-reference-205468b36b87","heading":"מקורות","text":"Development and socialization of self-regulation from infancy to adolescence (2023) סקירת־על שפורסמה ב־Developmental Review, המבוססת על 136 מאמרי סקירה ומטא־אנליזות. עוסקת בהתפתחות הוויסות העצמי מהינקות ועד גיל ההתבגרות, ובתפקידם של מבוגרים והסביבה החברתית."},{"id":"article-reference-b2b002601a21","heading":"מקורות","text":"Raghunathan et al. (2023) – What children do while they wait: The role of self-control strategies in delaying gratification מחקר שנערך בקרב 144 ילדים ובחן את ההתנהגויות והאסטרטגיות שבהן הם משתמשים בזמן המתנה לפרס."},{"id":"article-reference-07d786e1a8cf","heading":"מקורות","text":"Watts, Duncan & Quan (2018) – Revisiting the Marshmallow Test מחקר שבחן מחדש את הקשר בין דחיית סיפוקים בילדות לבין הישגים והתנהגות בגיל ההתבגרות, תוך התייחסות להשפעת הרקע המשפחתי והסביבה."},{"id":"article-reference-db1ce3e777e6","heading":"מקורות","text":"Sperber et al. (2024) – Delay of gratification and adult outcomes: The Marshmallow Test does not reliably predict adult functioning מחקר אורך שבחן 702 משתתפים עד גיל 26, ומצא שהביצועים במבחן המרשמלו בילדות אינם מנבאים באופן מהימן תפקוד והישגים בבגרות."}]}];
